INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u1-C1','kor',1,2,'u1',3,'흉내 내는 말 알기 — 소리를 흉내 낸 말·모양을 흉내 낸 말 구별',ARRAY['2국04-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u1-C2','kor',1,2,'u1',3,'흉내 내는 말을 넣어 문장 만들기 — 문장 상황에 어울리는 말 고르기, 실감 나는 까닭',ARRAY['2국04-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u1-C3','kor',1,2,'u1',5,'마음을 나타내는 흉내 내는 말 — 콩닥콩닥·부글부글·사르르 같은 말이 나타내는 마음 읽기',ARRAY['2국05-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u1-C4','kor',1,2,'u1',7,'기분을 나타내는 말 — 상황에 어울리는 기분 말 고르기, 기분 말과 물건 이름 구별',ARRAY['2국01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u1-C5','kor',1,2,'u1',9,'듣는 사람을 생각하며 기분 말하기 — 「나」로 시작해 있었던 일과 기분 말하기, 탓하지 않기',ARRAY['2국01-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u1-C6','kor',1,2,'u1',13,'문장의 짜임 — 누가·무엇을·어찌하다 순서로 뜻이 통하는 문장 만들기',ARRAY['2국04-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X01','kor',1,'u1',ARRAY['K1-2-u1-C1']::text[],'물건·사람·곳 이름을 흉내 내는 말로 고른다 (들판·나뭇잎을 흉내 내는 말로)','「소리가 나요? 모양이 보여요?」 두 질문으로 걸러 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X02','kor',1,'u1',ARRAY['K1-2-u1-C1']::text[],'소리를 흉내 낸 말과 모양을 흉내 낸 말을 뒤바꾼다 (개굴개굴을 모양으로)','말을 입으로 내 보고 「귀로 들은 것인지, 눈으로 본 것인지」 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X03','kor',1,'u1',ARRAY['K1-2-u1-C2']::text[],'문장 상황과 어긋나는 흉내 내는 말을 넣는다 (눈이 꼬르륵 쌓여요)','흉내 내는 말을 뺀 문장부터 읽고 「무엇이 어떻게 하는 장면인지」 그려 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X04','kor',1,'u1',ARRAY['K1-2-u1-C2']::text[],'흉내 내는 말은 문장을 길게 만드는 것이라고 여긴다 (실감·장면이 떠오르는 효과를 모름)','흉내 내는 말이 있는 문장과 없는 문장을 나란히 읽고 무엇이 보이는지 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X05','kor',1,'u1',ARRAY['K1-2-u1-C3']::text[],'물건에서 나는 소리 흉내를 마음을 나타낸 말로 고른다 (딸랑딸랑을 마음으로)','「누구 마음이 그런 거예요?」 — 마음의 임자를 찾게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X06','kor',1,'u1',ARRAY['K1-2-u1-C3']::text[],'흉내 내는 말이 나타내는 마음을 다르게 읽는다 (부글부글을 신난 마음으로)','그 말이 나온 앞뒤 일을 다시 읽고 좋은 일인지 속상한 일인지 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X07','kor',1,'u1',ARRAY['K1-2-u1-C4']::text[],'상황과 어긋나는 기분 말을 고른다 (도움을 받았는데 화나요)','「나라면 어떤 마음이 들까」 상황을 몸으로 떠올려 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X08','kor',1,'u1',ARRAY['K1-2-u1-C4']::text[],'물건 이름·하는 일을 기분을 나타내는 말로 고른다 (필통·달리기를 기분 말로)','기분 말은 「마음이 ~해요」로 바꿔 말할 수 있는지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X09','kor',1,'u1',ARRAY['K1-2-u1-C5']::text[],'상대를 탓하는 말을 기분 말하기로 여긴다 (너 때문에 다 망쳤어)','말의 첫 낱말이 「너」인지 「나」인지 짚어 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X10','kor',1,'u1',ARRAY['K1-2-u1-C5']::text[],'「나」로 시작만 하면 된다고 여겨 있었던 일이나 기분을 빠뜨리거나 탓하는 말을 넣는다 (나는 네가 미워)','「나는 (있었던 일)해서 (기분)했어」 틀에 한 칸씩 채워 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X11','kor',1,'u1',ARRAY['K1-2-u1-C5']::text[],'기분을 말하는 차례를 모른다 (큰 소리부터 내기·아무 말도 안 하기)','① 무슨 일 ② 내 기분 ③ 듣는 사람 ④ 「나」로 말하기 네 걸음 손가락으로 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X12','kor',1,'u1',ARRAY['K1-2-u1-C5','K1-2-u1-C4']::text[],'기분을 말할 필요를 못 느낀다 — 좋은 기분은 말 안 해도 된다고 여기거나(칭찬을 받고도 시큰둥), 기분을 말하면 무엇이 좋은지 모른다','고마운 마음도 말로 전하면 상대 기분이 어떻게 되는지 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X13','kor',1,'u1',ARRAY['K1-2-u1-C6']::text[],'누가·무엇을 자리를 바꿔 뜻이 뒤집힌 문장을 고른다 (도토리가 다람쥐를 먹습니다)','그림을 보며 「누가 하는 일인지」 손가락으로 짚고 첫 낱말 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X14','kor',1,'u1',ARRAY['K1-2-u1-C6']::text[],'무엇을 과 어울리지 않는 어찌하다를 고른다 (우산을 마십니다)','끝 낱말을 넣어 몸으로 해 보게 하기 — 할 수 없는 일이면 어긋난 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X15','kor',1,'u1',ARRAY['K1-2-u1-C5']::text[],'낱말의 뜻을 겉소리로 짐작한다 (「굳다」를 단단한 물건으로, 「나도 모르게」를 일부러로)','그 낱말이 나온 앞뒤 줄을 다시 읽고 어떤 마음·장면인지 말로 바꿔 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#1','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','친구가 무거운 짐을 들어 주었어요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],true,'{"seq":1,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"친구가 무거운 짐을 들어 주었어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"고마워요","correct":true},{"t":"화나요","mis":"K1-2-u1-X07"},{"t":"무서워요","mis":"K1-2-u1-X07"}],"explanation":["도움을 받으면 고마운 마음이 들어요.","화나거나 무서운 일이 아니에요 — 나를 도와준 일이에요.","「나라면 어떤 마음일까」 그 자리에 있다고 생각해 봐요."],"asset":{"type":"scene","icon":"🧒📦🙂","text":"친구가 짐을 들어 주었어요"},"variant_rule":{"alt":[{"stem":"생일에 친구에게 선물을 받았어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"기뻐요","correct":true},{"t":"속상해요","mis":"K1-2-u1-X07"},{"t":"지루해요","mis":"K1-2-u1-X07"}],"explanation":["선물을 받으면 기쁜 마음이 들어요.","속상하거나 지루한 일이 아니에요.","내가 선물을 받았다고 상상해 봐요."],"asset":{"type":"scene","icon":"🎁😊","text":"선물을 받았어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#2','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','아끼던 화분이 넘어져 흙이 쏟아졌어요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],true,'{"seq":2,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"아끼던 화분이 넘어져 흙이 쏟아졌어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"속상해요","correct":true},{"t":"즐거워요","mis":"K1-2-u1-X07"},{"t":"궁금해요","mis":"K1-2-u1-X07"}],"explanation":["아끼던 것이 망가지면 속상한 마음이 들어요.","즐겁거나 궁금한 일이 아니에요 — 소중한 것을 잃은 일이에요.","아끼던 물건이 망가졌던 때를 떠올려 봐요."],"asset":{"type":"scene","icon":"🪴😢","text":"화분이 넘어졌어요"},"variant_rule":{"alt":[{"stem":"꼭 잡고 있던 풍선이 하늘로 날아가 버렸어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"아쉬워요","correct":true},{"t":"신나요","mis":"K1-2-u1-X07"},{"t":"편안해요","mis":"K1-2-u1-X07"}],"explanation":["가지고 싶던 것을 놓치면 아쉬운 마음이 들어요.","신나거나 편안한 일이 아니에요.","풍선을 놓쳤을 때 손이 어떻게 될지 떠올려 봐요."],"asset":{"type":"scene","icon":"🎈😯","text":"풍선이 날아갔어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#3','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','다음 가운데 기분을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u1-X08']::text[],true,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"다음 가운데 기분을 나타내는 말은 어느 것인가요?","options":[{"t":"반가워요","correct":true},{"t":"필통","mis":"K1-2-u1-X08"},{"t":"운동장","mis":"K1-2-u1-X08"}],"explanation":["반가워요는 마음이 어떠한지 알려 주는 말이에요.","필통과 운동장은 물건과 장소의 이름이라 기분이 아니에요.","「마음이 ○○해요」로 바꿔 말할 수 있으면 기분을 나타내는 말이에요."],"variant_rule":{"alt":[{"stem":"다음 가운데 기분을 나타내는 말은 어느 것인가요?","options":[{"t":"부끄러워요","correct":true},{"t":"우산","mis":"K1-2-u1-X08"},{"t":"책상","mis":"K1-2-u1-X08"}],"explanation":["부끄러워요는 마음이 어떠한지 알려 주는 말이에요.","우산과 책상은 물건 이름이에요.","「마음이 ○○해요」로 바꿔 보면 알 수 있어요."],"asset":null},{"stem":"다음 가운데 기분을 나타내는 말은 어느 것인가요?","options":[{"t":"걱정돼요","correct":true},{"t":"달리기","mis":"K1-2-u1-X08"},{"t":"교실","mis":"K1-2-u1-X08"}],"explanation":["걱정돼요는 마음을 나타내는 말이에요.","달리기는 하는 일, 교실은 장소예요.","「마음이 걱정돼요」처럼 마음 앞에 붙여 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#4','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C1',1,'mc','auto','두 문장 가운데 비 오는 소리가 들리는 것 같은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X04']::text[],true,'{"seq":4,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"두 문장 가운데 비 오는 소리가 들리는 것 같은 문장은 어느 것인가요?","options":[{"t":"비가 주룩주룩 내려요.","correct":true},{"t":"비가 내려요.","mis":"K1-2-u1-X04"}],"explanation":["주룩주룩은 비 오는 소리를 흉내 낸 말이에요.","「비가 내려요」에는 소리를 옮긴 말이 없어요.","두 문장을 소리 내어 읽고 어느 쪽이 더 잘 떠오르는지 비교해 봐요."],"variant_rule":{"alt":[{"stem":"두 문장 가운데 눈 쌓이는 모양이 보이는 것 같은 문장은 어느 것인가요?","options":[{"t":"눈이 소복소복 쌓였어요.","correct":true},{"t":"눈이 쌓였어요.","mis":"K1-2-u1-X04"}],"explanation":["소복소복은 눈이 쌓이는 모양을 흉내 낸 말이에요.","「눈이 쌓였어요」에는 모양을 옮긴 말이 없어요.","흉내 내는 말이 있는 쪽이 눈앞에 그려져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#5','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',2,'mc','auto','이사 간 친구를 오랜만에 만났어요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],true,'{"seq":5,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"이사 간 친구를 오랜만에 만났어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"반가워요","correct":true},{"t":"서운해요","mis":"K1-2-u1-X07"},{"t":"심심해요","mis":"K1-2-u1-X07"}],"explanation":["보고 싶던 친구를 만나면 반가운 마음이 들어요.","서운하거나 심심한 일이 아니에요.","오랜만에 만나는 얼굴을 떠올려 봐요."],"asset":{"type":"scene","icon":"🧒👋🧒","text":"오랜만에 만났어요"},"variant_rule":{"alt":[{"stem":"처음 보는 큰 개가 짖으며 다가와요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"무서워요","correct":true},{"t":"뿌듯해요","mis":"K1-2-u1-X07"},{"t":"편안해요","mis":"K1-2-u1-X07"}],"explanation":["큰 소리로 짖으며 다가오면 무서운 마음이 들어요.","뿌듯하거나 편안한 일이 아니에요.","그 자리에 있다고 상상해 몸이 어떻게 되는지 느껴 봐요."],"asset":{"type":"scene","icon":"🐕😨","text":"큰 개가 짖어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#6','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',2,'match','auto','장면과 그때 드는 기분을 선으로 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K1-2-u1-C4","difficulty":2,"kind":"match","stem":"장면과 그때 드는 기분을 선으로 이어 보세요.","pairs":[{"l":"상을 받았어요","r":"뿌듯해요"},{"l":"만나기로 한 친구가 못 왔어요","r":"아쉬워요"},{"l":"깜깜한 방에 혼자 있어요","r":"무서워요"}],"mis":"K1-2-u1-X07","explanation":["상을 받으면 뿌듯하고, 기다리던 친구가 못 오면 아쉬워요.","깜깜한 방에 혼자 있으면 무서운 마음이 들어요.","장면마다 「나라면 어떤 마음일까」 하나씩 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"장면과 그때 드는 기분을 선으로 이어 보세요.","pairs":[{"l":"친구가 선물을 주었어요","r":"고마워요"},{"l":"처음으로 발표를 해요","r":"떨려요"},{"l":"아끼던 컵이 깨졌어요","r":"속상해요"}],"explanation":["선물을 받으면 고맙고, 처음 발표할 때는 떨려요.","아끼던 것이 깨지면 속상해요.","장면을 마음속으로 그려 보고 기분을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#7','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#8','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C2',2,'mc','auto','「눈이 소복소복 쌓였어요.」에서 흉내 내는 말은 어느 것인가요?',ARRAY['K1-2-u1-X01']::text[],true,'{"seq":8,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"「눈이 소복소복 쌓였어요.」에서 흉내 내는 말은 어느 것인가요?","options":[{"t":"소복소복","correct":true},{"t":"눈이","mis":"K1-2-u1-X01"},{"t":"쌓였어요","mis":"K1-2-u1-X01"}],"explanation":["소복소복은 눈이 쌓이는 모양을 흉내 낸 말이에요.","눈은 물건 이름이고, 쌓였어요는 하는 일을 나타내는 말이에요.","「모양이나 소리를 그대로 옮긴 말인가?」 물어보면 찾을 수 있어요."],"variant_rule":{"alt":[{"stem":"「아기가 아장아장 걸어요.」에서 흉내 내는 말은 어느 것인가요?","options":[{"t":"아장아장","correct":true},{"t":"아기가","mis":"K1-2-u1-X01"},{"t":"걸어요","mis":"K1-2-u1-X01"}],"explanation":["아장아장은 아기가 걷는 모양을 흉내 낸 말이에요.","아기는 사람, 걸어요는 하는 일이에요.","되풀이되는 소리로 된 말을 찾아봐요."],"asset":null},{"stem":"「개구리가 개굴개굴 울어요.」에서 흉내 내는 말은 어느 것인가요?","options":[{"t":"개굴개굴","correct":true},{"t":"개구리가","mis":"K1-2-u1-X01"},{"t":"울어요","mis":"K1-2-u1-X01"}],"explanation":["개굴개굴은 개구리 소리를 흉내 낸 말이에요.","개구리는 동물 이름, 울어요는 하는 일이에요.","입으로 내 보면 소리인지 알 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#9','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',2,'ox','auto','같은 일을 겪어도 사람마다 느끼는 기분이 다를 수 있어요.',ARRAY['K1-2-u1-X07']::text[],true,'{"seq":9,"concept":"K1-2-u1-C4","difficulty":2,"kind":"ox","stem":"같은 일을 겪어도 사람마다 느끼는 기분이 다를 수 있어요.","answer":"O","reason_options":[{"t":"비 오는 날 시원해서 좋은 친구도, 못 놀아서 아쉬운 친구도 있으니까","correct":true},{"t":"같은 일이면 기분도 꼭 같아야 하니까","mis":"K1-2-u1-X07"}],"mis":"K1-2-u1-X07","explanation":["같은 일이라도 사람마다 느끼는 기분은 달라요.","그래서 기분도 꼭 같아야 한다는 생각은 맞지 않아요.","내 기분에 꼭 맞는 말을 찾아 말하면 마음이 잘 전해져요."],"variant_rule":{"alt":[{"stem":"기분을 나타내는 말은 기뻐요와 슬퍼요 두 가지뿐이에요.","answer":"X","reason_options":[{"t":"반가워요·뿌듯해요·서운해요처럼 아주 많으니까","correct":true},{"t":"기분은 좋은 것과 나쁜 것 둘뿐이니까","mis":"K1-2-u1-X08"}],"explanation":["기분을 나타내는 말은 아주 많아요.","기쁘고 슬픈 것 말고도 반갑고, 뿌듯하고, 서운한 마음이 있어요.","내 마음에 꼭 맞는 말을 찾아봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#10','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C5',3,'mc','auto','기분을 말로 표현하면 무엇이 좋을까요?',ARRAY['K1-2-u1-X12']::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"기분을 말로 표현하면 무엇이 좋을까요?","options":[{"t":"내 마음을 다른 사람에게 알려 줄 수 있어요","correct":true},{"t":"달리기가 빨라져요","mis":"K1-2-u1-X12"},{"t":"글씨가 예뻐져요","mis":"K1-2-u1-X12"}],"explanation":["내 마음을 말로 알려 주면 서로 더 잘 지낼 수 있어요.","달리기나 글씨와는 상관없는 일이에요.","말하지 않으면 다른 사람은 내 마음을 알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#1','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C4',2,'mc','auto','놀이에 나만 끼워 주지 않았어요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],true,'{"seq":1,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"놀이에 나만 끼워 주지 않았어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"서운해요","correct":true},{"t":"즐거워요","mis":"K1-2-u1-X07"},{"t":"편안해요","mis":"K1-2-u1-X07"}],"explanation":["함께하고 싶은데 끼지 못하면 서운한 마음이 들어요.","즐겁거나 편안한 일이 아니에요.","그 자리에 서 있는 나를 떠올려 봐요."],"asset":{"type":"scene","icon":"🧒🚫⚽","text":"나만 빠졌어요"},"variant_rule":{"alt":[{"stem":"내 차례를 친구가 먼저 하라고 양보해 주었어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"고마워요","correct":true},{"t":"화나요","mis":"K1-2-u1-X07"},{"t":"지루해요","mis":"K1-2-u1-X07"}],"explanation":["양보를 받으면 고마운 마음이 들어요.","화나거나 지루한 일이 아니에요.","친구가 나를 생각해 준 일이에요."],"asset":{"type":"scene","icon":"🧒🙏🧒","text":"양보해 주었어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#2','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C2',2,'mc','auto','두 문장 가운데 나뭇잎이 떨어지는 모양이 눈앞에 보이는 것 같은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X04']::text[],true,'{"seq":2,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"두 문장 가운데 나뭇잎이 떨어지는 모양이 눈앞에 보이는 것 같은 문장은 어느 것인가요?","options":[{"t":"나뭇잎이 팔랑팔랑 떨어져요.","correct":true},{"t":"나뭇잎이 떨어져요.","mis":"K1-2-u1-X04"}],"explanation":["팔랑팔랑은 가볍게 흔들리며 떨어지는 모양을 흉내 낸 말이에요.","흉내 내는 말이 없으면 어떻게 떨어지는지 떠오르지 않아요.","흉내 내는 말은 그 모습을 눈앞에 그려 줘요."],"variant_rule":{"alt":[{"stem":"두 문장 가운데 시계 소리가 들리는 것 같은 문장은 어느 것인가요?","options":[{"t":"시계가 똑딱똑딱 가요.","correct":true},{"t":"시계가 가요.","mis":"K1-2-u1-X04"}],"explanation":["똑딱똑딱은 시계 소리를 흉내 낸 말이에요.","흉내 내는 말이 없으면 소리가 떠오르지 않아요.","소리 내어 읽으면 차이가 느껴져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#3','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C4',3,'error','auto','지우가 기분을 나타내는 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#4','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C4',3,'mc','auto','같은 비 오는 날인데 한 친구는 「시원해서 좋아요」, 다른 친구는 「못 놀아서 아쉬워요」라고 해요. 왜 그럴까요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":3,"kind":"mc","stem":"같은 비 오는 날인데 한 친구는 「시원해서 좋아요」, 다른 친구는 「못 놀아서 아쉬워요」라고 해요. 왜 그럴까요?","options":[{"t":"사람마다 느끼는 기분이 다를 수 있어서","correct":true},{"t":"한 친구가 틀리게 느껴서","mis":"K1-2-u1-X07"},{"t":"비가 너무 많이 와서","mis":"K1-2-u1-X07"}],"explanation":["같은 일이라도 사람마다 느끼는 기분은 다를 수 있어요.","기분에는 맞고 틀린 것이 없어요.","내 기분과 친구 기분이 다르면 서로 말해 주면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#5','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C4',3,'match','auto','장면과 그때 드는 기분을 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C4","difficulty":3,"kind":"match","stem":"장면과 그때 드는 기분을 선으로 이어 보세요.","pairs":[{"l":"처음으로 앞에 나가 발표해요","r":"떨려요"},{"l":"아끼던 인형을 잃어버렸어요","r":"속상해요"},{"l":"이사 간 친구를 다시 만났어요","r":"반가워요"},{"l":"어려운 일을 혼자 힘으로 해냈어요","r":"뿌듯해요"}],"mis":"K1-2-u1-X07","explanation":["처음 발표할 때는 떨리고, 아끼던 것을 잃으면 속상해요.","다시 만나면 반갑고, 혼자 해내면 뿌듯해요.","장면 속의 나를 떠올리며 하나씩 이어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#6','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C2',3,'blank','auto','빈칸에 알맞은 흉내 내는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#7','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C5',3,'ox','auto','기분을 말로 하면 서로 더 잘 지낼 수 있어요.',ARRAY['K1-2-u1-X12']::text[],false,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":3,"kind":"ox","stem":"기분을 말로 하면 서로 더 잘 지낼 수 있어요.","answer":"O","reason_options":[{"t":"내 마음을 알면 상대가 이해하거나 도와줄 수 있으니까","correct":true},{"t":"기분을 말하면 싸움만 되니까","mis":"K1-2-u1-X12"}],"mis":"K1-2-u1-X12","explanation":["말로 마음을 알려 주면 상대가 내 마음을 알고 이해할 수 있어요.","기분을 말한다고 싸움이 되는 게 아니에요 — 말하는 방법이 중요해요.","듣는 사람을 생각하며 말하면 마음이 잘 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#8','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C4',4,'sa','auto','친구가 넘어진 나를 일으켜 주었어요. 내 기분을 나타내는 말을 한 낱말로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u1-C4","difficulty":4,"kind":"sa","stem":"친구가 넘어진 나를 일으켜 주었어요. 내 기분을 나타내는 말을 한 낱말로 쓰세요.","answer":["고마워요","고마워","고맙다","고마웠어요","고마웠어","고마움","고마운마음","고마운","고맙습니다","감사해요","감사","감사합니다"],"explanation":["나를 도와준 친구에게는 고마운 마음이 들어요.","속상하거나 화나는 일이 아니에요.","「고마워요」처럼 마음이 어떠한지 알려 주는 말을 써요."],"variant_rule":{"alt":[{"stem":"열심히 쌓은 블록 탑이 와르르 무너졌어요. 내 기분을 나타내는 말을 한 낱말로 쓰세요.","answer":["속상해요","속상해","속상하다","속상했어요","속상했어","속상함","속상","아쉬워요","아쉬워","아쉽다","아쉬웠어요","슬퍼요","슬퍼","슬프다","슬펐어요"],"explanation":["열심히 만든 것이 무너지면 속상하거나 아쉬운 마음이 들어요.","기쁘거나 신나는 일이 아니에요.","내가 그 자리에 있다고 생각하고 마음을 말해 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#9','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C4',4,'essay','teacher','오늘 하루 가운데 기억에 남는 일을 하나 떠올려 「나는 ○○해서 ○○했어.」처럼 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C4","difficulty":4,"kind":"essay","stem":"오늘 하루 가운데 기억에 남는 일을 하나 떠올려 「나는 ○○해서 ○○했어.」처럼 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 나는 친구와 술래잡기를 해서 즐거웠어. — 있었던 일 + 기분을 나타내는 말이 모두 들어 있으면 맞아요.","scoring_points":["「나는」으로 시작했는가","있었던 일이 들어 있는가","기분을 나타내는 말이 들어 있는가"]},"explanation":["있었던 일 다음에 내 기분을 말해요.","기분을 나타내는 말은 즐거웠어·뿌듯했어·속상했어처럼 마음을 알려 주는 말이에요.","오늘 아침부터 차례로 떠올리면 한 가지는 꼭 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#10','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C2',4,'essay','teacher','「비가 내려요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"「비가 내려요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.","answer_guide":{"answer":"예: 비가 주룩주룩 내려요. / 비가 부슬부슬 내려요. / 비가 후드득 내려요. — 비와 어울리는 흉내 내는 말이면 맞아요.","scoring_points":["흉내 내는 말이 들어갔는가","비 오는 소리나 모양에 어울리는가","문장이 자연스러운가"]},"explanation":["주룩주룩·부슬부슬처럼 비 오는 소리나 모양을 흉내 낸 말을 넣어요.","꼬르륵처럼 비와 상관없는 소리는 어울리지 않아요.","창밖에 비가 오는 모습을 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#1','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],true,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"개굴개굴","correct":true},{"t":"아장아장","mis":"K1-2-u1-X02"},{"t":"훨훨","mis":"K1-2-u1-X02"}],"explanation":["개굴개굴은 개구리가 우는 소리를 그대로 옮긴 말이에요.","아장아장과 훨훨은 걷는 모양, 나는 모양을 옮긴 말이에요.","말을 입으로 내 보고 「귀로 들은 것인가」 물어봐요."],"variant_rule":{"alt":[{"stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"멍멍","correct":true},{"t":"데굴데굴","mis":"K1-2-u1-X02"},{"t":"뭉게뭉게","mis":"K1-2-u1-X02"}],"explanation":["멍멍은 강아지가 짖는 소리예요.","데굴데굴은 구르는 모양, 뭉게뭉게는 구름 모양이에요.","귀로 들리는 것인지 눈으로 보이는 것인지 나눠 봐요."],"asset":null},{"stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"딸랑딸랑","correct":true},{"t":"살금살금","mis":"K1-2-u1-X02"},{"t":"반짝반짝","mis":"K1-2-u1-X02"}],"explanation":["딸랑딸랑은 종이 울리는 소리예요.","살금살금은 걷는 모양, 반짝반짝은 빛나는 모양이에요.","소리는 귀, 모양은 눈으로 알아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#2','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],true,'{"seq":2,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"데굴데굴","correct":true},{"t":"짹짹","mis":"K1-2-u1-X02"},{"t":"딸랑딸랑","mis":"K1-2-u1-X02"}],"explanation":["데굴데굴은 공이 구르는 모양을 옮긴 말이에요.","짹짹은 새소리, 딸랑딸랑은 종소리예요.","눈으로 본 움직임을 옮긴 말이 모양을 흉내 낸 말이에요."],"variant_rule":{"alt":[{"stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"뒤뚱뒤뚱","correct":true},{"t":"야옹","mis":"K1-2-u1-X02"},{"t":"똑똑","mis":"K1-2-u1-X02"}],"explanation":["뒤뚱뒤뚱은 오리가 걷는 모양이에요.","야옹은 고양이 소리, 똑똑은 문 두드리는 소리예요.","몸으로 따라 할 수 있으면 모양을 흉내 낸 말이에요."],"asset":null},{"stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"깡충깡충","correct":true},{"t":"멍멍","mis":"K1-2-u1-X02"},{"t":"꼬르륵","mis":"K1-2-u1-X02"}],"explanation":["깡충깡충은 토끼가 뛰는 모양이에요.","멍멍과 꼬르륵은 소리예요.","뛰는 모습이 눈에 보이면 모양이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#3','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',1,'mc','auto','국수를 먹는 소리에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X03']::text[],true,'{"seq":3,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"국수를 먹는 소리에 어울리는 말은 어느 것인가요?","options":[{"t":"후루룩","correct":true},{"t":"딸랑딸랑","mis":"K1-2-u1-X03"},{"t":"데굴데굴","mis":"K1-2-u1-X03"}],"explanation":["후루룩은 국수를 빨아들일 때 나는 소리예요.","딸랑딸랑은 종소리, 데굴데굴은 구르는 모양이라 국수와 어울리지 않아요.","국수 먹는 모습을 떠올리며 소리를 내 봐요."],"asset":{"type":"scene","icon":"🍜"},"variant_rule":{"alt":[{"stem":"문을 두드리는 소리에 어울리는 말은 어느 것인가요?","options":[{"t":"똑똑","correct":true},{"t":"짹짹","mis":"K1-2-u1-X03"},{"t":"훨훨","mis":"K1-2-u1-X03"}],"explanation":["똑똑은 문을 두드릴 때 나는 소리예요.","짹짹은 새소리, 훨훨은 나는 모양이에요.","손으로 책상을 두드려 봐요."],"asset":{"type":"scene","icon":"🚪✊"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#4','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C2',1,'blank','auto','빈칸에 알맞은 흉내 내는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#5','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',2,'match','auto','그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u1-C1","difficulty":2,"kind":"match","stem":"그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.","pairs":[{"l":"🐸 개구리","r":"개굴개굴"},{"l":"❄️ 쌓인 눈","r":"소복소복"},{"l":"✏️ 연필 소리","r":"사각사각"}],"mis":"K1-2-u1-X03","explanation":["개구리는 개굴개굴 울고, 눈은 소복소복 쌓여요.","연필로 쓰면 사각사각 소리가 나요.","그림마다 소리나 모양을 먼저 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.","pairs":[{"l":"🐶 강아지","r":"멍멍"},{"l":"🌧️ 가는 비","r":"부슬부슬"},{"l":"🔔 종","r":"딸랑딸랑"}],"explanation":["강아지는 멍멍 짖고, 가는 비는 부슬부슬 내려요.","종은 딸랑딸랑 울려요.","그림을 보고 소리를 내 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#6','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',2,'mc','auto','다음 글에서 흉내 내는 말은 어느 것인가요?',ARRAY['K1-2-u1-X01']::text[],true,'{"seq":6,"concept":"K1-2-u1-C1","difficulty":2,"kind":"mc","stem":"다음 글에서 흉내 내는 말은 어느 것인가요?","options":[{"t":"뭉게뭉게","correct":true},{"t":"들판","mis":"K1-2-u1-X01"},{"t":"나뭇잎","mis":"K1-2-u1-X01"}],"explanation":["뭉게뭉게는 구름이 피어오르는 모양을 흉내 낸 말이에요.","들판은 장소, 나뭇잎은 물건 이름이에요.","되풀이되는 말 가운데 소리나 모양을 옮긴 것을 찾아요."],"asset":{"type":"passage","lines":["가을 들판에 구름이 뭉게뭉게 떠 있어요.","나뭇잎이 팔랑팔랑 떨어져요.","아이가 사과를 아삭아삭 먹어요."]},"variant_rule":{"alt":[{"stem":"다음 글에서 흉내 내는 말은 어느 것인가요?","options":[{"t":"살랑살랑","correct":true},{"t":"강아지","mis":"K1-2-u1-X01"},{"t":"꼬리","mis":"K1-2-u1-X01"}],"explanation":["살랑살랑은 꼬리를 흔드는 모양을 흉내 낸 말이에요.","강아지와 꼬리는 이름이에요.","움직임을 옮긴 말을 찾아요."],"asset":{"type":"passage","lines":["아침에 새가 짹짹 울어요.","강아지가 꼬리를 살랑살랑 흔들어요."]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#7','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',2,'mc','auto','힘없이 걸어가는 모양에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],true,'{"seq":7,"concept":"K1-2-u1-C1","difficulty":2,"kind":"mc","stem":"힘없이 걸어가는 모양에 어울리는 말은 어느 것인가요?","options":[{"t":"터벅터벅","correct":true},{"t":"짹짹","mis":"K1-2-u1-X02"},{"t":"아삭아삭","mis":"K1-2-u1-X02"}],"explanation":["터벅터벅은 힘없이 걷는 모양이에요.","짹짹과 아삭아삭은 소리라 걷는 모양이 아니에요.","걷는 모습을 몸으로 따라 해 봐요."],"asset":{"type":"scene","icon":"🚶😮‍💨"},"variant_rule":{"alt":[{"stem":"살짝살짝 조용히 걷는 모양에 어울리는 말은 어느 것인가요?","options":[{"t":"살금살금","correct":true},{"t":"멍멍","mis":"K1-2-u1-X02"},{"t":"후루룩","mis":"K1-2-u1-X02"}],"explanation":["살금살금은 소리 없이 조심스럽게 걷는 모양이에요.","멍멍과 후루룩은 소리예요.","발끝으로 걸어 봐요."],"asset":{"type":"scene","icon":"🐈🤫"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#8','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C2',2,'mc','auto','흉내 내는 말을 넣으면 무엇이 좋을까요?',ARRAY['K1-2-u1-X04']::text[],false,'{"seq":8,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"흉내 내는 말을 넣으면 무엇이 좋을까요?","options":[{"t":"그 모습이 눈앞에 잘 떠올라요","correct":true},{"t":"문장이 무조건 길어져요","mis":"K1-2-u1-X04"},{"t":"글자 수를 셀 수 있어요","mis":"K1-2-u1-X04"}],"explanation":["흉내 내는 말이 있으면 소리와 모양이 눈앞에 떠올라 더 실감 나요.","길어지려고 넣는 게 아니에요.","흉내 내는 말이 있는 문장과 없는 문장을 나란히 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#9','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',2,'ox','auto','「아삭아삭」은 소리를 흉내 낸 말이에요.',ARRAY['K1-2-u1-X02']::text[],true,'{"seq":9,"concept":"K1-2-u1-C1","difficulty":2,"kind":"ox","stem":"「아삭아삭」은 소리를 흉내 낸 말이에요.","answer":"O","reason_options":[{"t":"사과를 베어 물 때 나는 소리를 옮겼으니까","correct":true},{"t":"사과의 둥근 모양을 옮긴 말이니까","mis":"K1-2-u1-X02"}],"mis":"K1-2-u1-X02","explanation":["아삭아삭은 씹을 때 나는 소리예요.","사과의 모양을 옮긴 말이 아니에요.","말을 소리 내 보고 귀로 들은 것인지 물어봐요."],"variant_rule":{"alt":[{"stem":"「훨훨」은 소리를 흉내 낸 말이에요.","answer":"X","reason_options":[{"t":"나비가 날개를 저으며 나는 모양을 옮긴 말이니까","correct":true},{"t":"나비가 날 때 내는 소리니까","mis":"K1-2-u1-X02"}],"explanation":["훨훨은 나는 모양을 옮긴 말이에요.","나비는 날 때 소리를 내지 않아요.","눈으로 본 움직임이면 모양이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#10','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',3,'error','auto','지우가 소리를 흉내 낸 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#1','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C2',2,'blank','auto','빈칸에 알맞은 흉내 내는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#2','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',2,'mc','auto','다음 글에서 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02','K1-2-u1-X01']::text[],true,'{"seq":2,"concept":"K1-2-u1-C1","difficulty":2,"kind":"mc","stem":"다음 글에서 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"반짝반짝","correct":true},{"t":"개굴개굴","mis":"K1-2-u1-X02"},{"t":"별이","mis":"K1-2-u1-X01"}],"explanation":["반짝반짝은 별이 빛나는 모양을 옮긴 말이에요.","개굴개굴은 소리를 옮긴 말이고, 별은 이름이에요.","글에 흉내 내는 말이 둘 있으면 소리와 모양으로 나눠 봐요."],"asset":{"type":"passage","lines":["밤하늘에 별이 반짝반짝 빛나요.","연못에서 개구리가 개굴개굴 울어요."]},"variant_rule":{"alt":[{"stem":"다음 글에서 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"쨍그랑","correct":true},{"t":"데굴데굴","mis":"K1-2-u1-X02"},{"t":"유리컵이","mis":"K1-2-u1-X01"}],"explanation":["쨍그랑은 유리가 깨질 때 나는 소리예요.","데굴데굴은 구르는 모양, 유리컵은 이름이에요.","귀로 들리는 것을 찾아요."],"asset":{"type":"passage","lines":["공이 데굴데굴 굴러갔어요.","유리컵이 쨍그랑 깨졌어요."]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#3','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',3,'match','auto','그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"K1-2-u1-C1","difficulty":3,"kind":"match","stem":"그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.","pairs":[{"l":"🐥 병아리","r":"삐악삐악"},{"l":"⚽ 굴러가는 공","r":"데굴데굴"},{"l":"🌧️ 세찬 비","r":"주룩주룩"},{"l":"🦋 나비","r":"훨훨"}],"mis":"K1-2-u1-X03","explanation":["병아리는 삐악삐악 울고, 공은 데굴데굴 굴러요.","세찬 비는 주룩주룩 내리고, 나비는 훨훨 날아요.","소리인지 모양인지 먼저 나누면 이어 주기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#4','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C2',3,'error','auto','「눈이 꼬르륵 쌓였어요.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],true,'{"seq":4,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「눈이 꼬르륵 쌓였어요.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"꼬르륵은 배에서 나는 소리라 눈이 쌓이는 장면과 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"눈에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「쌓였어요」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["눈이 쌓이는 모양은 소복소복이에요.","꼬르륵은 배가 고플 때 나는 소리예요.","흉내 내는 말을 뺀 문장부터 읽고 어떤 장면인지 그려 봐요."],"variant_rule":{"alt":[{"stem":"「강아지가 아삭아삭 짖어요.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"아삭아삭은 씹는 소리라 강아지가 짖는 장면과 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"강아지에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「짖어요」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["강아지가 짖는 소리는 멍멍이에요.","아삭아삭은 사과 같은 것을 씹을 때 나는 소리예요.","장면을 먼저 그리고 그 장면의 소리를 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#5','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',3,'ox','auto','「딸랑딸랑」과 「뭉게뭉게」는 둘 다 소리를 흉내 낸 말이에요.',ARRAY['K1-2-u1-X02']::text[],true,'{"seq":5,"concept":"K1-2-u1-C1","difficulty":3,"kind":"ox","stem":"「딸랑딸랑」과 「뭉게뭉게」는 둘 다 소리를 흉내 낸 말이에요.","answer":"X","reason_options":[{"t":"뭉게뭉게는 구름이 피어오르는 모양을 옮긴 말이니까","correct":true},{"t":"둘 다 귀로 들은 소리를 옮긴 말이니까","mis":"K1-2-u1-X02"}],"mis":"K1-2-u1-X02","explanation":["딸랑딸랑은 종소리, 뭉게뭉게는 구름 모양이에요.","둘 다 소리는 아니에요.","하나씩 소리 내 보면 어느 쪽이 소리인지 알 수 있어요."],"variant_rule":{"alt":[{"stem":"「아장아장」과 「뒤뚱뒤뚱」은 둘 다 모양을 흉내 낸 말이에요.","answer":"O","reason_options":[{"t":"아기와 오리가 걷는 모습을 옮긴 말이니까","correct":true},{"t":"둘 다 걸을 때 나는 소리니까","mis":"K1-2-u1-X02"}],"explanation":["둘 다 걷는 모양을 옮긴 말이에요.","걷는 소리를 옮긴 말이 아니에요.","몸으로 따라 해 보면 모양이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#6','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C2',3,'mc','auto','강아지가 꼬리를 흔드는 모습이 눈앞에 보이는 것 같은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X04','K1-2-u1-X03']::text[],false,'{"seq":6,"concept":"K1-2-u1-C2","difficulty":3,"kind":"mc","stem":"강아지가 꼬리를 흔드는 모습이 눈앞에 보이는 것 같은 문장은 어느 것인가요?","options":[{"t":"강아지가 꼬리를 살랑살랑 흔들어요.","correct":true},{"t":"강아지가 꼬리를 흔들어요.","mis":"K1-2-u1-X04"},{"t":"강아지가 꼬리를 아삭아삭 흔들어요.","mis":"K1-2-u1-X03"}],"explanation":["살랑살랑은 가볍게 흔드는 모양을 흉내 낸 말이에요.","흉내 내는 말이 없으면 모습이 잘 안 떠오르고, 아삭아삭은 씹는 소리라 어울리지 않아요.","어울리는 흉내 내는 말을 넣어야 실감 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#7','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',3,'mc','auto','다음 글에 흉내 내는 말은 모두 몇 개인가요?',ARRAY['K1-2-u1-X01']::text[],true,'{"seq":7,"concept":"K1-2-u1-C1","difficulty":3,"kind":"mc","stem":"다음 글에 흉내 내는 말은 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"K1-2-u1-X01"},{"t":"4개","mis":"K1-2-u1-X01"}],"explanation":["딸랑딸랑·우르르·쨍쨍 — 세 개예요.","종·아이들·운동장·햇빛은 이름이라 흉내 내는 말이 아니에요.","줄마다 소리나 모양을 옮긴 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["종이 딸랑딸랑 울려요.","아이들이 우르르 달려 나가요.","운동장에 햇빛이 쨍쨍 내리쬐요."]},"variant_rule":{"alt":[{"stem":"다음 글에 흉내 내는 말은 모두 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"3개","mis":"K1-2-u1-X01"},{"t":"1개","mis":"K1-2-u1-X01"}],"explanation":["보글보글·살금살금 — 두 개예요.","국이 끓는 소리와 고양이가 걷는 모양이에요.","줄마다 하나씩 찾아 세어 봐요."],"asset":{"type":"passage","lines":["국이 보글보글 끓어요.","고양이가 살금살금 걸어와요.","엄마가 창문을 열었어요."]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#8','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',4,'sa','auto','다음 글에서 모양을 흉내 낸 말을 찾아 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u1-C1","difficulty":4,"kind":"sa","stem":"다음 글에서 모양을 흉내 낸 말을 찾아 쓰세요.","answer":["살포시","살포시앉았어요"],"explanation":["살포시는 나비가 가볍게 앉는 모양을 옮긴 말이에요.","붕붕은 벌이 나는 소리예요.","소리인지 모양인지 나눠 보면 하나가 남아요."],"asset":{"type":"passage","lines":["나비가 꽃 위에 살포시 앉았어요.","벌이 붕붕 날아다녀요."]},"variant_rule":{"alt":[{"stem":"다음 글에서 모양을 흉내 낸 말을 찾아 쓰세요.","answer":["꼬물꼬물","꼬물꼬물가요"],"explanation":["꼬물꼬물은 개미가 줄지어 가는 모양이에요.","맴맴은 매미가 우는 소리예요.","눈으로 보이는 움직임을 찾아요."],"asset":{"type":"passage","lines":["개미가 줄지어 꼬물꼬물 가요.","나무에서 매미가 맴맴 울어요."]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#9','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C2',4,'essay','teacher','「강아지가 달려와요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"「강아지가 달려와요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.","answer_guide":{"answer":"예: 강아지가 총총 달려와요. / 강아지가 후다닥 달려와요. / 강아지가 멍멍 짖으며 달려와요. — 달려오는 모습이나 소리에 어울리면 맞아요.","scoring_points":["흉내 내는 말이 들어갔는가","달려오는 장면과 어울리는가","문장이 자연스러운가"]},"explanation":["총총·후다닥처럼 달려오는 모양을 옮긴 말을 넣어요.","소복소복처럼 어울리지 않는 말은 장면이 어긋나요.","강아지가 달려오는 모습을 눈앞에 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#10','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',4,'essay','teacher','소리를 흉내 낸 말과 모양을 흉내 낸 말을 하나씩 쓰고, 그 말이 어떤 소리인지·어떤 모양인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C1","difficulty":4,"kind":"essay","stem":"소리를 흉내 낸 말과 모양을 흉내 낸 말을 하나씩 쓰고, 그 말이 어떤 소리인지·어떤 모양인지 쓰세요.","answer_guide":{"answer":"예: 소리 — 멍멍(강아지 짖는 소리) / 모양 — 깡충깡충(토끼가 뛰는 모양). 둘 다 알맞게 나누어 썼으면 맞아요.","scoring_points":["소리를 흉내 낸 말 하나가 맞는가","모양을 흉내 낸 말 하나가 맞는가","무엇의 소리·모양인지 썼는가"]},"explanation":["귀로 들은 것을 옮기면 소리, 눈으로 본 것을 옮기면 모양이에요.","같은 말을 두 곳에 쓰면 안 돼요.","우리 둘레의 동물이나 물건을 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#1','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',1,'mc','auto','「오늘 내 마음」을 읽고 답하세요. 처음 발표할 때 마음은 어땠나요?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":1,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「오늘 내 마음」을 읽고 답하세요. 처음 발표할 때 마음은 어땠나요?","options":[{"t":"떨렸어요","correct":true},{"t":"졸렸어요","mis":"K1-2-u1-X06"},{"t":"아무렇지 않았어요","mis":"K1-2-u1-X06"}],"explanation":["콩닥콩닥은 가슴이 뛰는 떨리는 마음을 나타내요.","졸리거나 아무렇지 않은 마음이라면 콩닥콩닥이라고 쓰지 않아요.","그 말이 나온 줄을 다시 읽고 어떤 일이 있었는지 봐요."],"asset":{"type":"passage","lines":["처음 발표할 때는 마음이 콩닥콩닥 뛰었어요.","줄넘기를 열 번 넘고 나니 마음이 훨훨 나는 것 같았어요.","동생이 내 그림에 낙서를 해서 마음이 부글부글 끓었어요.","짝꿍이 함께 놀자고 해서 마음이 사르르 풀렸어요."],"title":"오늘 내 마음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#2','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',1,'mc','auto','「부글부글」이 나타내는 마음은 어느 것인가요?',ARRAY['K1-2-u1-X06']::text[],true,'{"seq":2,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「부글부글」이 나타내는 마음은 어느 것인가요?","options":[{"t":"화나요","correct":true},{"t":"신나요","mis":"K1-2-u1-X06"},{"t":"졸려요","mis":"K1-2-u1-X06"}],"explanation":["부글부글은 속이 끓어오르는 화난 마음을 나타내요.","신나거나 졸린 마음과는 달라요.","물이 끓는 모습을 떠올리면 마음도 그렇게 끓는 거예요."],"variant_rule":{"alt":[{"stem":"「사르르」가 나타내는 마음은 어느 것인가요?","options":[{"t":"마음이 풀려요","correct":true},{"t":"무서워요","mis":"K1-2-u1-X06"},{"t":"화나요","mis":"K1-2-u1-X06"}],"explanation":["사르르는 굳었던 마음이 부드럽게 풀리는 것을 나타내요.","무섭거나 화나는 마음과는 반대예요.","눈이 사르르 녹는 모습을 떠올려 봐요."],"asset":null},{"stem":"「두근두근」이 나타내는 마음은 어느 것인가요?","options":[{"t":"설레요","correct":true},{"t":"지루해요","mis":"K1-2-u1-X06"},{"t":"편안해요","mis":"K1-2-u1-X06"}],"explanation":["두근두근은 가슴이 뛰는 설레는 마음이에요.","지루하거나 편안할 때는 가슴이 뛰지 않아요.","가슴에 손을 대고 뛰는 것을 느껴 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#3','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C2',1,'blank','auto','빈칸에 알맞은 흉내 내는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#4','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',1,'mc','auto','마음을 나타낸 흉내 내는 말은 어느 것인가요?',ARRAY['K1-2-u1-X05']::text[],true,'{"seq":4,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"마음을 나타낸 흉내 내는 말은 어느 것인가요?","options":[{"t":"콩닥콩닥","correct":true},{"t":"딸랑딸랑","mis":"K1-2-u1-X05"},{"t":"개굴개굴","mis":"K1-2-u1-X05"}],"explanation":["콩닥콩닥은 가슴이 뛰는 마음을 나타내요.","딸랑딸랑은 종, 개굴개굴은 개구리에서 나는 소리라 마음이 아니에요.","「누구 마음이 그런 거지?」 물어보면 골라져요."],"variant_rule":{"alt":[{"stem":"마음을 나타낸 흉내 내는 말은 어느 것인가요?","options":[{"t":"두근두근","correct":true},{"t":"사각사각","mis":"K1-2-u1-X05"},{"t":"멍멍","mis":"K1-2-u1-X05"}],"explanation":["두근두근은 가슴이 뛰는 마음이에요.","사각사각은 연필, 멍멍은 강아지 소리예요.","마음의 임자가 있으면 마음을 나타낸 말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#5','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',2,'match','auto','흉내 내는 말과 그 말이 나타내는 마음을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u1-C3","difficulty":2,"kind":"match","stem":"흉내 내는 말과 그 말이 나타내는 마음을 선으로 이어 보세요.","pairs":[{"l":"콩닥콩닥","r":"떨려요"},{"l":"부글부글","r":"화나요"},{"l":"사르르","r":"마음이 풀려요"},{"l":"훨훨","r":"신나요"}],"mis":"K1-2-u1-X06","explanation":["콩닥콩닥은 떨리는 마음, 부글부글은 화난 마음이에요.","사르르는 풀리는 마음, 훨훨은 신나서 날아갈 것 같은 마음이에요.","그 말이 나온 앞뒤 일을 떠올리면 마음이 보여요."],"variant_rule":{"alt":[{"stem":"흉내 내는 말과 그 말이 나타내는 마음을 선으로 이어 보세요.","pairs":[{"l":"두근두근","r":"설레요"},{"l":"조마조마","r":"걱정돼요"},{"l":"오싹","r":"무서워요"}],"explanation":["두근두근은 설레는 마음, 조마조마는 걱정되는 마음이에요.","오싹은 무서워서 소름이 돋는 마음이에요.","몸으로 어떻게 느껴지는지 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#6','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C2',2,'mc','auto','흉내 내는 말을 알맞게 넣은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X03']::text[],true,'{"seq":6,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"흉내 내는 말을 알맞게 넣은 문장은 어느 것인가요?","options":[{"t":"눈이 소복소복 쌓였어요.","correct":true},{"t":"눈이 꼬르륵 쌓였어요.","mis":"K1-2-u1-X03"},{"t":"눈이 후루룩 쌓였어요.","mis":"K1-2-u1-X03"}],"explanation":["눈이 쌓이는 모양은 소복소복이에요.","꼬르륵은 배, 후루룩은 국수와 어울리는 소리예요.","흉내 내는 말을 빼고 장면을 먼저 그려 봐요."],"variant_rule":{"alt":[{"stem":"흉내 내는 말을 알맞게 넣은 문장은 어느 것인가요?","options":[{"t":"아기가 아장아장 걸어요.","correct":true},{"t":"아기가 쨍그랑 걸어요.","mis":"K1-2-u1-X03"},{"t":"아기가 보글보글 걸어요.","mis":"K1-2-u1-X03"}],"explanation":["아기가 걷는 모양은 아장아장이에요.","쨍그랑은 깨지는 소리, 보글보글은 끓는 소리예요.","아기 걸음을 떠올려 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#7','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',2,'ox','auto','마음도 흉내 내는 말로 나타낼 수 있어요.',ARRAY['K1-2-u1-X05']::text[],false,'{"seq":7,"concept":"K1-2-u1-C3","difficulty":2,"kind":"ox","stem":"마음도 흉내 내는 말로 나타낼 수 있어요.","answer":"O","reason_options":[{"t":"콩닥콩닥처럼 마음속 느낌을 그대로 옮길 수 있으니까","correct":true},{"t":"흉내 내는 말은 물건에서 나는 소리에만 쓰니까","mis":"K1-2-u1-X05"}],"mis":"K1-2-u1-X05","explanation":["흉내 내는 말은 마음도 실감 나게 나타내요.","물건 소리에만 쓰는 게 아니에요.","기쁠 때, 화날 때 마음속에서 무슨 일이 일어나는지 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#8','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',2,'mc','auto','「오늘 내 마음」에서 「마음이 사르르 풀렸어요」는 어떤 뜻인가요?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":2,"kind":"mc","stem":"「오늘 내 마음」에서 「마음이 사르르 풀렸어요」는 어떤 뜻인가요?","options":[{"t":"속상했던 마음이 사라졌어요","correct":true},{"t":"더 화가 났어요","mis":"K1-2-u1-X06"},{"t":"졸음이 왔어요","mis":"K1-2-u1-X06"}],"explanation":["사르르는 굳었던 마음이 부드럽게 풀리는 것이에요.","짝꿍이 놀자고 해서 화났던 마음이 풀린 거예요.","앞 줄에서 무슨 일이 있었는지 다시 읽어 봐요."],"asset":{"type":"passage","lines":["처음 발표할 때는 마음이 콩닥콩닥 뛰었어요.","줄넘기를 열 번 넘고 나니 마음이 훨훨 나는 것 같았어요.","동생이 내 그림에 낙서를 해서 마음이 부글부글 끓었어요.","짝꿍이 함께 놀자고 해서 마음이 사르르 풀렸어요."],"title":"오늘 내 마음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#9','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C2',2,'blank','auto','빈칸에 알맞은 흉내 내는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#10','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',3,'error','auto','지우가 마음을 나타낸 흉내 내는 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#1','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',2,'mc','auto','「강아지를 찾은 날」을 읽고 답하세요. 강아지가 보이지 않았을 때 마음은 어땠나요?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":1,"concept":"K1-2-u1-C3","difficulty":2,"kind":"mc","stem":"「강아지를 찾은 날」을 읽고 답하세요. 강아지가 보이지 않았을 때 마음은 어땠나요?","options":[{"t":"놀랐어요","correct":true},{"t":"신났어요","mis":"K1-2-u1-X06"},{"t":"지루했어요","mis":"K1-2-u1-X06"}],"explanation":["철렁 내려앉는 마음은 깜짝 놀란 마음이에요.","신나거나 지루한 일이 아니에요 — 강아지가 없어진 일이에요.","그 줄에 무슨 일이 있었는지 다시 읽어 봐요."],"asset":{"type":"passage","lines":["상을 받은 날, 마음이 둥실둥실 떠오르는 것 같았어요.","집에 오니 강아지가 보이지 않아 마음이 철렁 내려앉았어요.","골목에서 찾은 강아지를 안으니 마음이 포근포근했어요."],"title":"강아지를 찾은 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#2','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C2',2,'blank','auto','빈칸에 알맞은 흉내 내는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#3','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',3,'match','auto','흉내 내는 말과 그 말이 나타내는 마음을 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"K1-2-u1-C3","difficulty":3,"kind":"match","stem":"흉내 내는 말과 그 말이 나타내는 마음을 선으로 이어 보세요.","pairs":[{"l":"둥실둥실","r":"신나요"},{"l":"철렁","r":"놀라요"},{"l":"포근포근","r":"편안해요"},{"l":"부글부글","r":"화나요"}],"mis":"K1-2-u1-X06","explanation":["둥실둥실은 떠오르듯 신나는 마음, 철렁은 놀란 마음이에요.","포근포근은 편안한 마음, 부글부글은 화난 마음이에요.","「강아지를 찾은 날」에서 각 말이 나온 자리를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#4','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',3,'mc','auto','「마음이 훨훨 나는 것 같았어요.」 앞에 올 일로 어울리는 것은 어느 것인가요?',ARRAY['K1-2-u1-X06']::text[],true,'{"seq":4,"concept":"K1-2-u1-C3","difficulty":3,"kind":"mc","stem":"「마음이 훨훨 나는 것 같았어요.」 앞에 올 일로 어울리는 것은 어느 것인가요?","options":[{"t":"줄넘기를 열 번이나 넘었어요.","correct":true},{"t":"아끼던 연필이 부러졌어요.","mis":"K1-2-u1-X06"},{"t":"무서운 꿈을 꾸었어요.","mis":"K1-2-u1-X06"}],"explanation":["훨훨은 신나서 날아갈 것 같은 마음이라 기쁜 일 뒤에 와요.","연필이 부러지거나 무서운 꿈을 꾸면 신나지 않아요.","그 마음이 들려면 어떤 일이 있어야 할지 거꾸로 생각해 봐요."],"variant_rule":{"alt":[{"stem":"「마음이 부글부글 끓었어요.」 앞에 올 일로 어울리는 것은 어느 것인가요?","options":[{"t":"동생이 내 그림에 낙서를 했어요.","correct":true},{"t":"친구가 생일 선물을 주었어요.","mis":"K1-2-u1-X06"},{"t":"할머니가 안아 주셨어요.","mis":"K1-2-u1-X06"}],"explanation":["부글부글은 화난 마음이라 속상한 일 뒤에 와요.","선물을 받거나 안기면 화나지 않아요.","마음이 먼저인지 일이 먼저인지 차례를 생각해 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#5','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C2',3,'error','auto','「마음이 부글부글 끓어서 정말 기뻤어요.」 이 문장은 무엇이 어긋났나요?',ARRAY['K1-2-u1-X06','K1-2-u1-X03','K1-2-u1-X05']::text[],true,'{"seq":5,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「마음이 부글부글 끓어서 정말 기뻤어요.」 이 문장은 무엇이 어긋났나요?","options":[{"t":"부글부글은 화난 마음인데 기뻤다고 했어요","correct":true,"mis_target":"K1-2-u1-X06"},{"t":"「끓어서」라는 말이 잘못되었어요","mis":"K1-2-u1-X03"},{"t":"부글부글은 물건 소리라 마음에 쓸 수 없어요","mis":"K1-2-u1-X05"}],"explanation":["부글부글은 속이 끓어오르는 화난 마음이에요.","기쁜 마음이라면 훨훨이나 둥실둥실이 어울려요.","흉내 내는 말과 뒤에 오는 기분이 같은 방향인지 봐요."],"variant_rule":{"alt":[{"stem":"「마음이 사르르 풀려서 화가 났어요.」 이 문장은 무엇이 어긋났나요?","options":[{"t":"사르르는 풀리는 마음인데 화가 났다고 했어요","correct":true,"mis_target":"K1-2-u1-X06"},{"t":"「풀려서」라는 말이 잘못되었어요","mis":"K1-2-u1-X03"},{"t":"사르르는 눈에만 쓰는 말이에요","mis":"K1-2-u1-X05"}],"explanation":["사르르는 굳었던 마음이 풀리는 것이에요.","화가 났다면 부글부글이 어울려요.","앞뒤 말이 같은 마음을 가리키는지 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#6','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',3,'ox','auto','「사르르」는 화가 난 마음을 나타내요.',ARRAY['K1-2-u1-X06']::text[],true,'{"seq":6,"concept":"K1-2-u1-C3","difficulty":3,"kind":"ox","stem":"「사르르」는 화가 난 마음을 나타내요.","answer":"X","reason_options":[{"t":"굳은 마음이 부드럽게 풀리는 것을 나타내니까","correct":true},{"t":"사르르는 무섭게 들리니까","mis":"K1-2-u1-X06"}],"mis":"K1-2-u1-X06","explanation":["사르르는 눈이 녹듯 마음이 풀리는 것이에요.","화가 난 마음은 부글부글이에요.","「오늘 내 마음」 마지막 줄을 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"「콩닥콩닥」은 편안하게 쉬는 마음을 나타내요.","answer":"X","reason_options":[{"t":"가슴이 뛰는 떨리는 마음을 나타내니까","correct":true},{"t":"콩닥콩닥은 조용한 소리니까","mis":"K1-2-u1-X06"}],"explanation":["콩닥콩닥은 가슴이 뛰는 떨리는 마음이에요.","편안할 때는 가슴이 뛰지 않아요.","발표 앞에 선 나를 떠올려 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#7','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',3,'mc','auto','「발표하는 날」을 읽고 답하세요. 「조마조마」와 어울리는 마음은 어느 것인가요?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":7,"concept":"K1-2-u1-C3","difficulty":3,"kind":"mc","stem":"「발표하는 날」을 읽고 답하세요. 「조마조마」와 어울리는 마음은 어느 것인가요?","options":[{"t":"걱정돼요","correct":true},{"t":"뿌듯해요","mis":"K1-2-u1-X06"},{"t":"지루해요","mis":"K1-2-u1-X06"}],"explanation":["조마조마는 어떻게 될까 걱정되어 마음을 졸이는 것이에요.","뿌듯하거나 지루한 마음이 아니에요.","발표 차례가 다가올 때 내 마음을 떠올려 봐요."],"asset":{"type":"passage","lines":["발표 차례가 다가오자 마음이 조마조마했어요.","발표를 마치자 마음이 후련했어요.","친구들이 손뼉을 쳐 주어 마음이 두근두근했어요."],"title":"발표하는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#8','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',4,'sa','auto','「마음이 콩닥콩닥 뛰었어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":4,"kind":"sa","stem":"「마음이 콩닥콩닥 뛰었어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.","answer":["떨려요","떨려","떨렸어요","떨렸어","떨린다","떨림","떨리는","설레요","설레","설렜어요","설렘","긴장","긴장돼요","긴장했어요","긴장해요","두근두근","두근거려요"],"explanation":["콩닥콩닥은 가슴이 뛰는 떨리는 마음이에요.","화나거나 졸린 마음이 아니에요.","발표를 앞둔 나를 떠올리면 마음이 보여요."],"variant_rule":{"alt":[{"stem":"「마음이 부글부글 끓었어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.","answer":["화나요","화나","화났어요","화났어","화가나요","화가났어요","화","화남","화가난다","화난다","화가났다","속상해요","속상해","속상했어요","짜증나요","짜증"],"explanation":["부글부글은 속이 끓는 화난 마음이에요.","신나거나 편안한 마음이 아니에요.","끓는 냄비를 떠올려 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#9','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C2',4,'essay','teacher','요즘 있었던 일을 하나 떠올려 마음을 나타내는 흉내 내는 말을 넣어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"요즘 있었던 일을 하나 떠올려 마음을 나타내는 흉내 내는 말을 넣어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 상을 받아서 마음이 훨훨 나는 것 같았어요. / 동생이 내 장난감을 망가뜨려서 마음이 부글부글 끓었어요. — 있었던 일 + 마음 흉내 내는 말이 어울리면 맞아요.","scoring_points":["있었던 일이 들어 있는가","마음을 나타낸 흉내 내는 말이 있는가","일과 마음이 서로 어울리는가"]},"explanation":["있었던 일 다음에 그때 마음을 흉내 내는 말로 써요.","콩닥콩닥·부글부글·사르르·두근두근 가운데 골라도 좋아요.","일과 마음이 같은 방향인지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#10','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',4,'essay','teacher','「마음이 사르르 풀렸어요.」 이 문장 앞에 어떤 일이 있었을지 한 문장으로 지어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C3","difficulty":4,"kind":"essay","stem":"「마음이 사르르 풀렸어요.」 이 문장 앞에 어떤 일이 있었을지 한 문장으로 지어 쓰세요.","answer_guide":{"answer":"예: 다투었던 친구가 먼저 사과해 주어서 / 엄마가 안아 주셔서 — 굳었던 마음이 풀릴 만한 일이면 맞아요.","scoring_points":["마음이 풀릴 만한 일인가","한 문장으로 썼는가","앞뒤가 자연스럽게 이어지는가"]},"explanation":["사르르 풀리려면 먼저 마음이 굳어 있어야 해요.","친구가 놀자고 하거나 사과해 주면 마음이 풀려요.","「오늘 내 마음」 마지막 줄을 본보기로 삼아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#1','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','오래 기다린 소풍날 아침이에요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],true,'{"seq":1,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"오래 기다린 소풍날 아침이에요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"신나요","correct":true},{"t":"무서워요","mis":"K1-2-u1-X07"},{"t":"지루해요","mis":"K1-2-u1-X07"}],"explanation":["기다리던 일이 다가오면 설레고 신나요.","무섭거나 지루한 일이 아니에요.","소풍 가방을 메는 나를 떠올려 봐요."],"asset":{"type":"scene","icon":"🎒🌞","text":"소풍날 아침"},"variant_rule":{"alt":[{"stem":"내 발표 차례가 바로 다음이에요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"떨려요","correct":true},{"t":"편안해요","mis":"K1-2-u1-X07"},{"t":"심심해요","mis":"K1-2-u1-X07"}],"explanation":["발표를 앞두면 가슴이 뛰고 떨려요.","편안하거나 심심한 일이 아니에요.","앞에 나가기 직전을 떠올려 봐요."],"asset":{"type":"scene","icon":"🧒😬📄","text":"발표 바로 전"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#2','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','듣는 사람을 생각한 말은 어느 것인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X10']::text[],true,'{"seq":2,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"듣는 사람을 생각한 말은 어느 것인가요?","options":[{"t":"나는 그림이 지워져서 속상했어.","correct":true},{"t":"너 때문에 다 망쳤잖아!","mis":"K1-2-u1-X09"},{"t":"다 망쳤어. 됐어.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 있었던 일과 내 기분을 말했어요.","「너 때문에」는 탓하는 말이고, 「됐어」는 무슨 일인지 기분이 어떤지 알 수 없어요.","첫 낱말이 「나」인지 「너」인지 봐요."],"variant_rule":{"alt":[{"stem":"듣는 사람을 생각한 말은 어느 것인가요?","options":[{"t":"나는 혼자 남아서 서운했어.","correct":true},{"t":"너희 다 미워!","mis":"K1-2-u1-X09"},{"t":"됐어, 몰라.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말했어요.","「너희 다 미워」는 탓하는 말, 「됐어」는 기분이 안 보여요.","「나는 ○○해서 ○○했어」 틀에 맞는지 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#3','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',1,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#4','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','기분을 말하기 전에 가장 먼저 할 일은 무엇인가요?',ARRAY['K1-2-u1-X11']::text[],false,'{"seq":4,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"기분을 말하기 전에 가장 먼저 할 일은 무엇인가요?","options":[{"t":"무슨 일이 있었는지 생각하기","correct":true},{"t":"큰 소리부터 내기","mis":"K1-2-u1-X11"},{"t":"아무 말도 하지 않기","mis":"K1-2-u1-X11"}],"explanation":["무슨 일이 있었는지부터 차근차근 생각해요.","큰 소리부터 내거나 아무 말도 안 하면 마음이 전해지지 않아요.","① 무슨 일 ② 내 기분 ③ 듣는 사람 ④ 「나」로 말하기 — 손가락으로 세어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#5','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C4',2,'match','auto','장면과 그때 드는 기분을 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C4","difficulty":2,"kind":"match","stem":"장면과 그때 드는 기분을 선으로 이어 보세요.","pairs":[{"l":"넘어진 나를 친구가 일으켜 줌","r":"고마워요"},{"l":"비가 와서 소풍이 미루어짐","r":"아쉬워요"},{"l":"혼자 힘으로 해냄","r":"뿌듯해요"},{"l":"깜깜한 방에 혼자 있음","r":"무서워요"}],"mis":"K1-2-u1-X07","explanation":["도움을 받으면 고맙고, 기다리던 일이 미루어지면 아쉬워요.","혼자 해내면 뿌듯하고, 깜깜한 곳에 혼자 있으면 무서워요.","장면마다 「나라면」 하고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#6','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C4',2,'mc','auto','놀이에 나만 끼워 주지 않았어요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],true,'{"seq":6,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"놀이에 나만 끼워 주지 않았어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"서운해요","correct":true},{"t":"즐거워요","mis":"K1-2-u1-X07"},{"t":"편안해요","mis":"K1-2-u1-X07"}],"explanation":["함께하고 싶은데 끼지 못하면 서운해요.","즐겁거나 편안한 일이 아니에요.","혼자 서 있는 나를 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"잃어버린 줄 알았던 필통을 서랍에서 찾았어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"기뻐요","correct":true},{"t":"속상해요","mis":"K1-2-u1-X07"},{"t":"무서워요","mis":"K1-2-u1-X07"}],"explanation":["잃어버린 것을 다시 찾으면 기쁘고 마음이 놓여요.","속상하거나 무서운 일이 아니에요.","찾은 순간의 얼굴을 떠올려 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#7','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',2,'ox','auto','「나」로 시작해 말하면 상대를 탓하지 않고 내 마음을 전할 수 있어요.',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":2,"kind":"ox","stem":"「나」로 시작해 말하면 상대를 탓하지 않고 내 마음을 전할 수 있어요.","answer":"O","reason_options":[{"t":"있었던 일과 내 기분만 말하게 되니까","correct":true},{"t":"「너」로 시작해야 내 마음이 잘 전해지니까","mis":"K1-2-u1-X09"}],"mis":"K1-2-u1-X09","explanation":["「나」로 시작하면 내가 겪은 일과 내 기분을 말하게 돼요.","「너」로 시작하면 탓하는 말이 되기 쉬워요.","「나는 ○○해서 ○○했어」로 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#8','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','듣는 사람을 생각한 말은 어느 것인가요?',ARRAY['K1-2-u1-X09']::text[],true,'{"seq":8,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"듣는 사람을 생각한 말은 어느 것인가요?","options":[{"t":"나는 놀라서 마음이 떨렸어","correct":true},{"t":"다 너 때문이야","mis":"K1-2-u1-X09"},{"t":"너는 왜 맨날 그러니","mis":"K1-2-u1-X09"}],"explanation":["「나」로 시작해 내 기분을 말했어요.","「너 때문이야」와 「너는 왜」는 상대를 탓하는 말이에요.","탓하는 말은 듣는 사람 마음을 굳게 해요."],"variant_rule":{"alt":[{"stem":"듣는 사람을 생각한 말은 어느 것인가요?","options":[{"t":"나는 기다려 줘서 고마웠어","correct":true},{"t":"너 진짜 느리다","mis":"K1-2-u1-X09"},{"t":"너 때문에 늦었잖아","mis":"K1-2-u1-X09"}],"explanation":["「나」로 시작해 고마운 마음을 말했어요.","나머지는 상대를 탓하거나 놀리는 말이에요.","첫 낱말을 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#9','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','듣는 사람을 생각하며 말할 때 생각할 것이 아닌 것은 어느 것인가요?',ARRAY['K1-2-u1-X11']::text[],false,'{"seq":9,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"듣는 사람을 생각하며 말할 때 생각할 것이 아닌 것은 어느 것인가요?","options":[{"t":"내 목소리를 제일 크게 하기","correct":true},{"t":"무슨 일이 있었는지","mis":"K1-2-u1-X11"},{"t":"듣는 사람의 기분","mis":"K1-2-u1-X11"}],"explanation":["목소리를 크게 하는 것은 생각할 일이 아니에요.","무슨 일이 있었는지, 듣는 사람 기분은 어떨지는 꼭 생각해요.","네 걸음 가운데 없는 것을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#10','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',3,'error','auto','지우가 말했어요. 「너 때문에 내 그림이 지워졌잖아!」
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#1','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C4',2,'mc','auto','같은 놀이터에서 한 친구는 「신나요」, 다른 친구는 「지루해요」라고 해요. 왜 그럴까요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":1,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"같은 놀이터에서 한 친구는 「신나요」, 다른 친구는 「지루해요」라고 해요. 왜 그럴까요?","options":[{"t":"사람마다 느끼는 기분이 다를 수 있어서","correct":true},{"t":"지루하다는 친구가 잘못 느껴서","mis":"K1-2-u1-X07"},{"t":"놀이터가 좁아서","mis":"K1-2-u1-X07"}],"explanation":["같은 일이라도 사람마다 느끼는 기분은 달라요.","기분에는 맞고 틀린 것이 없어요.","서로 다른 기분을 말로 알려 주면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#2','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#3','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',3,'match','auto','상황과 그때 할 수 있는 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"K1-2-u1-C5","difficulty":3,"kind":"match","stem":"상황과 그때 할 수 있는 말을 선으로 이어 보세요.","pairs":[{"l":"친구가 나를 기다려 주었어요","r":"나는 기다려 줘서 고마웠어"},{"l":"뒤에서 갑자기 밀렸어요","r":"나는 갑자기 밀려서 놀랐어"},{"l":"놀이에서 혼자 남았어요","r":"나는 혼자 남아서 서운했어"},{"l":"친구가 짐을 들어 주었어요","r":"나는 도와줘서 든든했어"}],"mis":"K1-2-u1-X10","explanation":["모두 「나」로 시작해 있었던 일과 기분을 말해요.","상황마다 있었던 일이 다르니 기분도 달라요.","말 속의 「○○해서」를 상황과 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#4','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',3,'mc','auto','친구의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X10']::text[],true,'{"seq":4,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"친구의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"나는 말없이 써서 속상했어.","correct":true},{"t":"너 도둑이야!","mis":"K1-2-u1-X09"},{"t":"됐어, 몰라.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 있었던 일과 내 기분을 말해요.","「도둑」은 탓하는 말이고, 「됐어」는 기분이 전해지지 않아요.","내 마음을 알려야 친구가 다음에 물어보고 쓸 수 있어요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"네 물감 좀 썼어."},{"who":"나","text":"…"}]},"variant_rule":{"alt":[{"stem":"친구의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"나는 약속에 늦게 와서 걱정했어.","correct":true},{"t":"너 진짜 느려 터졌어!","mis":"K1-2-u1-X09"},{"t":"상관없어.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말해요.","「느려 터졌어」는 탓하는 말, 「상관없어」는 기분이 없어요.","기다리며 든 마음을 말해요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"미안, 늦었지?"},{"who":"나","text":"…"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#5','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',3,'error','auto','「나는 네가 정말 미워.」 이 말은 「나」로 시작했는데 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],true,'{"seq":5,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 네가 정말 미워.」 이 말은 「나」로 시작했는데 무엇이 잘못되었나요?","options":[{"t":"있었던 일과 내 기분 대신 상대를 탓하는 말을 넣었어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」을 「너는」으로 바꿔야 해요","mis":"K1-2-u1-X09"},{"t":"더 짧게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["「나」로 시작해도 「네가 미워」는 탓하는 말이에요.","「나는 약속을 어겨서 속상했어」처럼 있었던 일과 기분을 넣어요.","「나는 ○○해서 ○○했어」 두 칸이 다 있는지 봐요."],"variant_rule":{"alt":[{"stem":"「나는 너 같은 애랑 안 놀아.」 이 말은 「나」로 시작했는데 무엇이 잘못되었나요?","options":[{"t":"있었던 일과 내 기분 대신 상대를 밀어내는 말을 넣었어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」을 빼야 해요","mis":"K1-2-u1-X09"},{"t":"더 크게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["「나」로 시작해도 상대를 밀어내는 말이면 마음이 전해지지 않아요.","「나는 놀이에 끼지 못해서 서운했어」처럼 말해요.","두 칸(일·기분)을 채워 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#6','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C4',3,'ox','auto','기분을 나타내는 말은 좋은 기분에만 써요.',ARRAY['K1-2-u1-X12']::text[],false,'{"seq":6,"concept":"K1-2-u1-C4","difficulty":3,"kind":"ox","stem":"기분을 나타내는 말은 좋은 기분에만 써요.","answer":"X","reason_options":[{"t":"서운해요·아쉬워요처럼 속상한 마음도 말로 나타내니까","correct":true},{"t":"나쁜 기분은 말하면 안 되니까","mis":"K1-2-u1-X12"}],"mis":"K1-2-u1-X12","explanation":["속상한 마음도 기분을 나타내는 말로 전할 수 있어요.","기분을 말한다고 나쁜 것이 아니에요 — 말하는 방법이 중요해요.","속상할 때일수록 「나」로 시작해 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#7','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',3,'mc','auto','듣는 사람을 생각하며 말하는 차례예요. 세 번째 걸음은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#8','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C4',4,'sa','auto','어려운 일을 혼자 힘으로 해냈어요. 내 기분을 나타내는 말을 한 낱말로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u1-C4","difficulty":4,"kind":"sa","stem":"어려운 일을 혼자 힘으로 해냈어요. 내 기분을 나타내는 말을 한 낱말로 쓰세요.","answer":["뿌듯해요","뿌듯해","뿌듯하다","뿌듯했어요","뿌듯했어","뿌듯함","뿌듯","자랑스러워요","자랑스러워","자랑스럽다","자랑스러웠어요","기뻐요","기뻐","기쁘다","기뻤어요","신나요","신나","신났어요","기분좋아요","좋아요"],"explanation":["혼자 해냈을 때는 뿌듯한 마음이 들어요.","속상하거나 무서운 일이 아니에요.","해냈을 때 가슴이 어떻게 되는지 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"깜깜한 방에 혼자 있어요. 내 기분을 나타내는 말을 한 낱말로 쓰세요.","answer":["무서워요","무서워","무섭다","무서웠어요","무서웠어","무서움","무서운","겁나요","겁나","겁났어요","두려워요","두려워","불안해요","불안해"],"explanation":["깜깜한 곳에 혼자 있으면 무서운 마음이 들어요.","신나거나 편안한 일이 아니에요.","불이 꺼진 방을 떠올려 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#9','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','「너는 왜 새치기를 하니!」를 「나」로 시작하는 말로 바꿔 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"「너는 왜 새치기를 하니!」를 「나」로 시작하는 말로 바꿔 쓰세요.","answer_guide":{"answer":"예: 나는 오래 기다려서 마음이 급했어. / 나는 순서가 밀려서 속상했어. — 「나」로 시작 + 있었던 일 + 기분이 들어 있으면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분을 나타내는 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","탓하는 말 대신 내가 겪은 일을 말해요.","「그네 앞에서」의 네 번째 줄을 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#10','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','다음 가운데 하나를 골라 「나는 ○○해서 ○○했어.」로 쓰세요.
(친구가 기다려 주었을 때 · 놀이에 끼지 못했을 때 · 상을 받았을 때)','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"다음 가운데 하나를 골라 「나는 ○○해서 ○○했어.」로 쓰세요.\n(친구가 기다려 주었을 때 · 놀이에 끼지 못했을 때 · 상을 받았을 때)","answer_guide":{"answer":"예: 나는 친구가 기다려 줘서 고마웠어. / 나는 놀이에 끼지 못해서 서운했어. / 나는 상을 받아서 뿌듯했어. — 고른 상황과 기분이 어울리면 맞아요.","scoring_points":["「나」로 시작했는가","고른 상황이 있었던 일로 들어 있는가","상황에 어울리는 기분 말인가"]},"explanation":["상황을 하나 골라 그 일을 「○○해서」에 넣어요.","그때 든 마음을 뒤에 붙여요.","세 상황 모두 답이 될 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#1','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','「그네 앞에서」를 읽고 답하세요. 친구의 얼굴이 굳은 까닭은 무엇인가요?',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":1,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"「그네 앞에서」를 읽고 답하세요. 친구의 얼굴이 굳은 까닭은 무엇인가요?","options":[{"t":"탓하는 큰 소리를 들어서","correct":true},{"t":"그네가 너무 낮아서","mis":"K1-2-u1-X09"},{"t":"비가 내려서","mis":"K1-2-u1-X09"}],"explanation":["「너는 왜 새치기를 하니!」라는 탓하는 말을 들어서예요.","그네나 비 때문이 아니에요.","두 번째 줄과 세 번째 줄을 이어서 읽어 봐요."],"asset":{"type":"passage","lines":["그네를 타려고 한참 기다렸는데 다른 친구가 먼저 앉았어요.","나도 모르게 큰 소리가 나왔어요. \"너는 왜 새치기를 하니!\"","그 말을 들은 친구의 얼굴이 굳었어요. 마음이 편하지 않았어요.","숨을 한 번 쉬고 다시 말했어요. \"나는 오래 기다려서 마음이 급했어.\"","친구가 웃으며 말했어요. \"몰랐어. 열까지 세고 바꿔 탈까?\""],"title":"그네 앞에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#2','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','「그네 앞에서」에서 다시 말할 때는 어떻게 말했나요?',ARRAY['K1-2-u1-X11']::text[],false,'{"seq":2,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"「그네 앞에서」에서 다시 말할 때는 어떻게 말했나요?","options":[{"t":"「나」로 시작해 있었던 일과 내 기분을 말했어요","correct":true},{"t":"더 큰 소리로 말했어요","mis":"K1-2-u1-X11"},{"t":"아무 말도 하지 않았어요","mis":"K1-2-u1-X11"}],"explanation":["「나는 오래 기다려서 마음이 급했어」라고 말했어요.","큰 소리를 내거나 말을 안 한 게 아니에요.","네 번째 줄을 다시 읽어 봐요."],"asset":{"type":"passage","lines":["그네를 타려고 한참 기다렸는데 다른 친구가 먼저 앉았어요.","나도 모르게 큰 소리가 나왔어요. \"너는 왜 새치기를 하니!\"","그 말을 들은 친구의 얼굴이 굳었어요. 마음이 편하지 않았어요.","숨을 한 번 쉬고 다시 말했어요. \"나는 오래 기다려서 마음이 급했어.\"","친구가 웃으며 말했어요. \"몰랐어. 열까지 세고 바꿔 탈까?\""],"title":"그네 앞에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#3','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','짝꿍이 내 그림을 칭찬해 주었어요. 어떻게 말할까요?',ARRAY['K1-2-u1-X12']::text[],true,'{"seq":3,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"짝꿍이 내 그림을 칭찬해 주었어요. 어떻게 말할까요?","options":[{"t":"나는 칭찬을 들어서 뿌듯했어.","correct":true},{"t":"그림 잘 그리는 게 뭐 어때서.","mis":"K1-2-u1-X12"},{"t":"됐어, 그런 말 하지 마.","mis":"K1-2-u1-X12"}],"explanation":["좋은 기분도 「나」로 시작해 말해요.","시큰둥하게 받으면 칭찬해 준 친구 마음이 서운해져요.","고마운 마음도 말로 전하면 서로 더 기뻐요."],"asset":{"type":"scene","icon":"🎨👍"},"variant_rule":{"alt":[{"stem":"친구가 내 생일을 기억하고 축하해 주었어요. 어떻게 말할까요?","options":[{"t":"나는 네가 기억해 줘서 정말 기뻤어.","correct":true},{"t":"그게 뭐라고.","mis":"K1-2-u1-X12"},{"t":"알았어, 됐어.","mis":"K1-2-u1-X12"}],"explanation":["기쁜 마음도 「나」로 시작해 말해요.","시큰둥하게 받으면 축하해 준 친구가 서운해요.","좋은 기분은 말할수록 더 커져요."],"asset":{"type":"scene","icon":"🎂🧒"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#4','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',1,'blank','auto','동생이 내 색종이를 다 썼어요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#5','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',2,'match','auto','낱말과 뜻을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u1-C5","difficulty":2,"kind":"match","stem":"낱말과 뜻을 선으로 이어 보세요.","pairs":[{"l":"급하다","r":"빨리 하고 싶어 마음이 바쁘다"},{"l":"솔직하다","r":"숨기지 않고 있는 그대로 말하다"},{"l":"차분하다","r":"서두르지 않고 조용하다"},{"l":"굳다","r":"부드럽던 것이 딱딱해지다"}],"mis":"K1-2-u1-X15","explanation":["급하다는 마음이 바쁜 것, 솔직하다는 있는 그대로 말하는 것이에요.","차분하다는 조용한 것, 굳다는 딱딱해지는 것이에요.","「그네 앞에서」에서 그 낱말이 쓰인 자리를 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"낱말과 뜻을 선으로 이어 보세요.","pairs":[{"l":"서운하다","r":"마음이 섭섭하다"},{"l":"든든하다","r":"마음이 믿음직하고 편안하다"},{"l":"난처하다","r":"어떻게 해야 할지 몰라 곤란하다"}],"explanation":["서운하다는 섭섭한 마음, 든든하다는 믿음직한 마음이에요.","난처하다는 어찌할지 몰라 곤란한 것이에요.","그 마음이 들 만한 상황을 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#6','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','줄을 서다 뒤에서 밀렸어요. 어떻게 말할까요?',ARRAY['K1-2-u1-X09']::text[],true,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"줄을 서다 뒤에서 밀렸어요. 어떻게 말할까요?","options":[{"t":"나는 갑자기 밀려서 놀랐어.","correct":true},{"t":"너 진짜 밉다!","mis":"K1-2-u1-X09"},{"t":"야, 저리 가.","mis":"K1-2-u1-X09"}],"explanation":["탓하지 않고 있었던 일과 내 기분을 말해요.","「밉다」와 「저리 가」는 상대를 탓하고 밀어내는 말이에요.","놀란 마음을 「나」로 시작해 말해요."],"asset":{"type":"scene","icon":"🧍🧍💨"},"variant_rule":{"alt":[{"stem":"친구가 내 우산을 말없이 쓰고 갔어요. 어떻게 말할까요?","options":[{"t":"나는 우산이 없어서 비를 맞았어. 속상했어.","correct":true},{"t":"너 왜 남의 걸 훔쳐!","mis":"K1-2-u1-X09"},{"t":"너랑 안 놀아.","mis":"K1-2-u1-X09"}],"explanation":["있었던 일과 내 기분을 「나」로 시작해 말해요.","「훔쳐」와 「안 놀아」는 탓하고 밀어내는 말이에요.","비를 맞은 일을 그대로 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#7','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C4',2,'mc','auto','아끼던 화분이 없어졌어요. 이때 들 수 있는 기분이 아닌 것은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":7,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"아끼던 화분이 없어졌어요. 이때 들 수 있는 기분이 아닌 것은 어느 것인가요?","options":[{"t":"뿌듯해요","correct":true},{"t":"걱정돼요","mis":"K1-2-u1-X07"},{"t":"속상해요","mis":"K1-2-u1-X07"}],"explanation":["아끼던 것이 없어지면 뿌듯할 리 없어요.","걱정되고 속상한 마음은 들 수 있어요.","「없는 것」을 묻는 문제예요 — 어울리는 것을 먼저 지워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#8','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',2,'ox','auto','화가 난 마음은 잘못된 것이에요.',ARRAY['K1-2-u1-X11']::text[],false,'{"seq":8,"concept":"K1-2-u1-C5","difficulty":2,"kind":"ox","stem":"화가 난 마음은 잘못된 것이에요.","answer":"X","reason_options":[{"t":"화가 나는 것은 잘못이 아니고, 어떻게 말하느냐가 중요하니까","correct":true},{"t":"화를 내면 언제나 나쁜 아이가 되니까","mis":"K1-2-u1-X11"}],"mis":"K1-2-u1-X11","explanation":["화가 난 마음 자체는 잘못이 아니에요.","말하는 방법에 따라 듣는 사람 마음이 달라져요.","「그네 앞에서」의 첫 말과 다시 한 말을 비교해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#9','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','「그네 앞에서」에서 친구가 웃으며 「열까지 세고 바꿔 탈까?」라고 한 까닭은 무엇인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":9,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"「그네 앞에서」에서 친구가 웃으며 「열까지 세고 바꿔 탈까?」라고 한 까닭은 무엇인가요?","options":[{"t":"탓하지 않고 기분을 말해 주어서","correct":true},{"t":"그네가 새것으로 바뀌어서","mis":"K1-2-u1-X09"},{"t":"더 큰 소리를 내서","mis":"K1-2-u1-X11"}],"explanation":["「나」로 시작해 기분을 말하자 친구 마음이 풀렸어요.","그네가 바뀌거나 소리를 더 낸 게 아니에요.","네 번째 줄 다음에 다섯 번째 줄이 온 까닭을 생각해요."],"asset":{"type":"passage","lines":["그네를 타려고 한참 기다렸는데 다른 친구가 먼저 앉았어요.","나도 모르게 큰 소리가 나왔어요. \"너는 왜 새치기를 하니!\"","그 말을 들은 친구의 얼굴이 굳었어요. 마음이 편하지 않았어요.","숨을 한 번 쉬고 다시 말했어요. \"나는 오래 기다려서 마음이 급했어.\"","친구가 웃으며 말했어요. \"몰랐어. 열까지 세고 바꿔 탈까?\""],"title":"그네 앞에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#10','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',3,'error','auto','「나는 네가 새치기해서 정말 나쁜 애라고 생각했어.」 이 말은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 네가 새치기해서 정말 나쁜 애라고 생각했어.」 이 말은 무엇이 잘못되었나요?","options":[{"t":"「나」로 시작했지만 내 기분 대신 상대를 나쁘다고 탓했어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나」로 시작한 것이 잘못이에요","mis":"K1-2-u1-X09"},{"t":"더 길게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["「나쁜 애」는 탓하는 말이에요.","「나는 오래 기다려서 마음이 급했어」처럼 내 기분을 말해요.","「나」로 시작해도 뒤에 탓이 오면 마음이 굳어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#1','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',2,'mc','auto','「빌려준 색연필」을 읽고 답하세요. 짝이 고개를 푹 숙인 까닭은 무엇인가요?',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":1,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"「빌려준 색연필」을 읽고 답하세요. 짝이 고개를 푹 숙인 까닭은 무엇인가요?","options":[{"t":"탓하는 말을 듣고 마음이 상해서","correct":true},{"t":"색연필이 너무 무거워서","mis":"K1-2-u1-X09"},{"t":"잠이 와서","mis":"K1-2-u1-X09"}],"explanation":["「너는 왜 남의 걸 함부로 써!」라는 탓하는 말을 들어서예요.","색연필이나 잠 때문이 아니에요.","두 번째 줄과 세 번째 줄을 이어 읽어요."],"asset":{"type":"passage","lines":["짝이 내 색연필을 빌려 가서 부러뜨렸어요.","나는 \"너는 왜 남의 걸 함부로 써!\" 하고 소리쳤어요.","짝은 고개를 푹 숙였어요.","나는 다시 말했어요. \"나는 아끼던 색연필이 부러져서 속상했어.\"","짝이 말했어요. \"미안해. 내가 새것으로 사 줄게.\""],"title":"빌려준 색연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#2','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',2,'mc','auto','「빌려준 색연필」에서 처음 한 말과 다시 한 말은 무엇이 다른가요?',ARRAY['K1-2-u1-X11','K1-2-u1-X09']::text[],false,'{"seq":2,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"「빌려준 색연필」에서 처음 한 말과 다시 한 말은 무엇이 다른가요?","options":[{"t":"다시 한 말은 「나」로 시작해 있었던 일과 기분을 말했어요","correct":true},{"t":"다시 한 말이 더 커졌어요","mis":"K1-2-u1-X11"},{"t":"다시 한 말은 탓만 했어요","mis":"K1-2-u1-X09"}],"explanation":["처음 말은 「너는 왜」로 탓했고, 다시 한 말은 「나는」으로 시작했어요.","소리가 커지거나 탓이 늘어난 게 아니에요.","두 말의 첫 낱말을 비교해 봐요."],"asset":{"type":"passage","lines":["짝이 내 색연필을 빌려 가서 부러뜨렸어요.","나는 \"너는 왜 남의 걸 함부로 써!\" 하고 소리쳤어요.","짝은 고개를 푹 숙였어요.","나는 다시 말했어요. \"나는 아끼던 색연필이 부러져서 속상했어.\"","짝이 말했어요. \"미안해. 내가 새것으로 사 줄게.\""],"title":"빌려준 색연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#3','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',3,'match','auto','상황과 그때 할 수 있는 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"K1-2-u1-C5","difficulty":3,"kind":"match","stem":"상황과 그때 할 수 있는 말을 선으로 이어 보세요.","pairs":[{"l":"친구가 물감을 내 옷에 쏟았어요","r":"나는 옷이 젖어서 당황했어"},{"l":"친구가 약속에 늦게 왔어요","r":"나는 오래 기다려서 걱정했어"},{"l":"친구가 나를 놀이에 끼워 주었어요","r":"나는 끼워 줘서 기뻤어"},{"l":"친구가 내 자리에 앉았어요","r":"나는 앉을 곳이 없어서 난처했어"}],"mis":"K1-2-u1-X10","explanation":["모두 「나」로 시작해 있었던 일과 기분을 말해요.","좋은 일이든 속상한 일이든 같은 틀로 말할 수 있어요.","「○○해서」 부분을 상황과 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#4','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',3,'mc','auto','동생의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X10']::text[],true,'{"seq":4,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"동생의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"나는 허락 없이 써서 속상했어.","correct":true},{"t":"너 다시는 만지지 마!","mis":"K1-2-u1-X09"},{"t":"나는 네가 정말 싫어.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 있었던 일과 내 기분을 말해요.","「만지지 마」는 탓하는 말이고, 「네가 싫어」는 「나」로 시작했지만 탓이에요.","허락 없이 쓴 일과 그때 마음을 말해요."],"asset":{"type":"speech","turns":[{"who":"동생","text":"언니(형) 게임기 내가 썼어."},{"who":"나","text":"…"}]},"variant_rule":{"alt":[{"stem":"친구의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"나는 안 물어보고 먹어서 서운했어.","correct":true},{"t":"너 진짜 욕심쟁이야!","mis":"K1-2-u1-X09"},{"t":"나는 너 때문에 화나.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말해요.","「욕심쟁이」는 탓하는 말이고, 「너 때문에」는 「나」로 시작해도 탓이에요.","있었던 일을 그대로 말해요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"네 과자 내가 먹었어."},{"who":"나","text":"…"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#5','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',3,'error','auto','「나는 화가 났어.」 이 말에는 무엇이 빠졌나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],true,'{"seq":5,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 화가 났어.」 이 말에는 무엇이 빠졌나요?","options":[{"t":"무슨 일이 있었는지가 빠졌어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」이 빠졌어요","mis":"K1-2-u1-X09"},{"t":"말이 너무 길어요","mis":"K1-2-u1-X11"}],"explanation":["왜 화가 났는지 있었던 일을 말해야 상대가 알 수 있어요.","「나는」은 이미 있고, 말이 길지도 않아요.","「나는 ○○해서 화가 났어」로 채워 봐요."],"variant_rule":{"alt":[{"stem":"「나는 색연필이 부러졌어.」 이 말에는 무엇이 빠졌나요?","options":[{"t":"그때 내 기분이 빠졌어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」이 빠졌어요","mis":"K1-2-u1-X09"},{"t":"있었던 일이 빠졌어요","mis":"K1-2-u1-X10"}],"explanation":["있었던 일만 있고 기분이 없어요.","「나는 색연필이 부러져서 속상했어」처럼 기분을 붙여요.","두 칸(일·기분)이 다 있는지 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#6','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',3,'ox','auto','좋은 기분은 굳이 말하지 않아도 돼요.',ARRAY['K1-2-u1-X12']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":3,"kind":"ox","stem":"좋은 기분은 굳이 말하지 않아도 돼요.","answer":"X","reason_options":[{"t":"고마운 마음도 말하면 상대가 더 기뻐하니까","correct":true},{"t":"좋은 기분은 얼굴만 봐도 다 아니까","mis":"K1-2-u1-X12"}],"mis":"K1-2-u1-X12","explanation":["좋은 기분도 말로 전하면 서로 더 기뻐요.","얼굴만으로는 마음이 다 전해지지 않아요.","칭찬을 받았을 때 「나는 뿌듯했어」라고 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#7','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',3,'mc','auto','「나도 모르게 큰 소리가 나왔어요.」에서 「나도 모르게」의 뜻은 무엇인가요?',ARRAY['K1-2-u1-X15']::text[],true,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"「나도 모르게 큰 소리가 나왔어요.」에서 「나도 모르게」의 뜻은 무엇인가요?","options":[{"t":"생각하기도 전에 저절로","correct":true},{"t":"일부러 크게","mis":"K1-2-u1-X15"},{"t":"아주 작게","mis":"K1-2-u1-X15"}],"explanation":["「나도 모르게」는 생각할 틈도 없이 저절로 그렇게 되었다는 뜻이에요.","일부러 한 것도, 작게 한 것도 아니에요.","앞뒤 줄을 읽으면 뜻이 보여요."],"variant_rule":{"alt":[{"stem":"「숨을 한 번 쉬고 다시 말했어요.」에서 「숨을 한 번 쉬고」는 무엇을 했다는 뜻인가요?","options":[{"t":"마음을 가라앉히고","correct":true},{"t":"숨바꼭질을 하고","mis":"K1-2-u1-X15"},{"t":"빨리 달리고","mis":"K1-2-u1-X15"}],"explanation":["숨을 한 번 쉬는 것은 급한 마음을 가라앉히는 것이에요.","놀이나 달리기가 아니에요.","화가 났을 때 해 볼 수 있는 방법이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#8','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',4,'sa','auto','「숨기지 않고 있는 그대로 말하다」라는 뜻의 낱말을 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u1-C5","difficulty":4,"kind":"sa","stem":"「숨기지 않고 있는 그대로 말하다」라는 뜻의 낱말을 쓰세요.","answer":["솔직하다","솔직","솔직해요","솔직하게","솔직함","솔직한"],"explanation":["숨기지 않고 있는 그대로 말하는 것을 「솔직하다」라고 해요.","급하다·차분하다와는 뜻이 달라요.","기분을 말할 때는 솔직하게 떠올려요."],"variant_rule":{"alt":[{"stem":"「서두르지 않고 조용하다」라는 뜻의 낱말을 쓰세요.","answer":["차분하다","차분","차분해요","차분하게","차분함","차분한"],"explanation":["서두르지 않고 조용한 것을 「차분하다」라고 해요.","급하다와는 반대예요.","숨을 한 번 쉬면 차분해져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#9','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','「너는 왜 내 지우개를 가져가!」를 「나」로 시작하는 말로 바꿔 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"「너는 왜 내 지우개를 가져가!」를 「나」로 시작하는 말로 바꿔 쓰세요.","answer_guide":{"answer":"예: 나는 지우개가 없어져서 당황했어. / 나는 말도 없이 가져가서 속상했어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분을 나타내는 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","「왜 가져가」 대신 지우개가 없어진 일을 말해요.","「빌려준 색연필」 네 번째 줄을 본보기로 삼아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#10','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','「그네 앞에서」에서 만약 다시 말하지 않고 큰 소리로 끝났다면 어떻게 되었을까요? 그렇게 생각한 까닭도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"「그네 앞에서」에서 만약 다시 말하지 않고 큰 소리로 끝났다면 어떻게 되었을까요? 그렇게 생각한 까닭도 쓰세요.","answer_guide":{"answer":"예: 친구와 사이가 나빠졌을 것 같아요. 탓하는 말을 들으면 마음이 굳기 때문이에요. — 결과와 까닭이 이어져 있으면 맞아요.","scoring_points":["어떻게 되었을지 썼는가","까닭을 썼는가","탓하는 말의 효과와 이어지는가"]},"explanation":["탓하는 말을 들은 친구는 마음이 굳어 있었어요.","다시 말하지 않았다면 굳은 채로 끝났을 거예요.","세 번째 줄에서 이야기가 멈췄다고 상상해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#1','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','실수로 친구 그림에 물을 쏟았어요. 어떻게 말할까요?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],true,'{"seq":1,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"실수로 친구 그림에 물을 쏟았어요. 어떻게 말할까요?","options":[{"t":"나는 물을 쏟아서 정말 미안해.","correct":true},{"t":"그림을 왜 거기에 두었어?","mis":"K1-2-u1-X09"},{"t":"아무 말 없이 자리를 떠나요.","mis":"K1-2-u1-X11"}],"explanation":["있었던 일과 미안한 마음을 함께 말해요.","「왜 거기에」는 탓하는 말이고, 말없이 떠나면 마음이 전해지지 않아요.","내가 한 일을 그대로 말해요."],"asset":{"type":"scene","icon":"💧🎨😥"},"variant_rule":{"alt":[{"stem":"실수로 친구 발을 밟았어요. 어떻게 말할까요?","options":[{"t":"나는 발을 밟아서 미안해. 많이 아팠어?","correct":true},{"t":"네가 발을 거기 두니까 그렇지.","mis":"K1-2-u1-X09"},{"t":"못 본 척해요.","mis":"K1-2-u1-X11"}],"explanation":["내가 한 일과 미안한 마음을 말해요.","「네가 그러니까」는 탓하는 말이고, 못 본 척은 마음이 전해지지 않아요.","상대가 아팠을지도 물어봐요."],"asset":{"type":"scene","icon":"🦶😣"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#2','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','친구가 발표를 앞두고 떨고 있어요. 어떻게 말할까요?',ARRAY['K1-2-u1-X09','K1-2-u1-X12']::text[],false,'{"seq":2,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"친구가 발표를 앞두고 떨고 있어요. 어떻게 말할까요?","options":[{"t":"나도 떨렸어. 나는 네가 잘할 것 같아.","correct":true},{"t":"그런 것도 못 하니?","mis":"K1-2-u1-X09"},{"t":"나는 관심 없어.","mis":"K1-2-u1-X12"}],"explanation":["마음을 알아주는 말이 힘이 돼요.","「못 하니」는 놀리는 말이고, 「관심 없어」는 친구를 외롭게 해요.","내가 떨렸던 때를 떠올려 말해요."],"asset":{"type":"scene","icon":"🧒😬📄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#3','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','가족과 나들이를 왔어요. 내 기분을 어떻게 말할까요?',ARRAY['K1-2-u1-X09','K1-2-u1-X10']::text[],false,'{"seq":3,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"가족과 나들이를 왔어요. 내 기분을 어떻게 말할까요?","options":[{"t":"나는 함께 걸어서 마음이 편안해요.","correct":true},{"t":"여기 왜 왔어?","mis":"K1-2-u1-X09"},{"t":"재미없어. 됐어.","mis":"K1-2-u1-X10"}],"explanation":["좋은 기분도 「나」로 시작해 말하면 더 좋아요.","「왜 왔어」는 탓하는 말, 「됐어」는 무슨 기분인지 모르게 해요.","함께 걷는 기분을 말로 전해요."],"asset":{"type":"scene","icon":"🧺🌳🚶"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#4','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','역할놀이를 할 때 지킬 점은 무엇인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":4,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"역할놀이를 할 때 지킬 점은 무엇인가요?","options":[{"t":"역할이어도 바르고 고운 말을 써요","correct":true},{"t":"이길 때까지 크게 소리쳐요","mis":"K1-2-u1-X09"},{"t":"한 사람이 계속 같은 역할만 해요","mis":"K1-2-u1-X11"}],"explanation":["놀이에서도 「나」로 시작하는 바르고 고운 말을 써요.","소리치거나 한 사람만 하면 놀이가 아니에요.","역할을 바꾸어 여러 기분을 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#5','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',2,'match','auto','상황과 그때 할 수 있는 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C5","difficulty":2,"kind":"match","stem":"상황과 그때 할 수 있는 말을 선으로 이어 보세요.","pairs":[{"l":"실수로 친구 옷을 적셨어요","r":"나는 옷을 적셔서 미안해."},{"l":"친구가 넘어져 아파해요","r":"나는 네가 다쳐서 걱정돼."},{"l":"가족과 나들이를 갔어요","r":"나는 함께 나와서 즐거워."},{"l":"친구에게 도움을 받았어요","r":"나는 도와줘서 고마워."}],"mis":"K1-2-u1-X10","explanation":["상황마다 있었던 일이 다르니 기분도 달라요.","미안해·걱정돼·즐거워·고마워 — 모두 「나」로 시작해요.","「○○해서」와 상황을 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#6','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','역할놀이에서 쓰면 좋은 말은 어느 것인가요?',ARRAY['K1-2-u1-X09']::text[],true,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"역할놀이에서 쓰면 좋은 말은 어느 것인가요?","options":[{"t":"나는 기다려 줘서 고마워","correct":true},{"t":"너 때문에 다 틀렸어","mis":"K1-2-u1-X09"},{"t":"저리 가","mis":"K1-2-u1-X09"}],"explanation":["「나」로 시작해 기분을 말한 말이에요.","「너 때문에」와 「저리 가」는 탓하고 밀어내는 말이에요.","놀이에서도 듣는 사람을 생각해요."],"variant_rule":{"alt":[{"stem":"역할놀이에서 쓰면 좋은 말은 어느 것인가요?","options":[{"t":"나는 늦어서 미안해","correct":true},{"t":"네가 먼저 왔어야지","mis":"K1-2-u1-X09"},{"t":"너 때문에 늦었어","mis":"K1-2-u1-X09"}],"explanation":["내가 한 일과 미안한 마음을 「나」로 시작해 말했어요.","나머지 둘은 탓하는 말이에요.","첫 낱말을 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#7','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C4',2,'mc','auto','역할놀이예요. 비 오는 날 친구가 내게 우산을 같이 씌워 주었어요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],true,'{"seq":7,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"역할놀이예요. 비 오는 날 친구가 내게 우산을 같이 씌워 주었어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"고마워요","correct":true},{"t":"아쉬워요","mis":"K1-2-u1-X07"},{"t":"지루해요","mis":"K1-2-u1-X07"}],"explanation":["나를 챙겨 주면 고마운 마음이 들어요.","아쉽거나 지루한 일이 아니에요.","우산 속에 함께 선 나를 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"역할놀이예요. 내 차례인데 친구가 자꾸 끼어들어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"답답해요","correct":true},{"t":"신나요","mis":"K1-2-u1-X07"},{"t":"편안해요","mis":"K1-2-u1-X07"}],"explanation":["내 차례를 못 하면 답답하거나 속상해요.","신나거나 편안한 일이 아니에요.","기다리는 나를 떠올려 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#8','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',2,'ox','auto','역할놀이에서 화난 역할을 맡으면 상대를 마음껏 탓해도 돼요.',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":8,"concept":"K1-2-u1-C5","difficulty":2,"kind":"ox","stem":"역할놀이에서 화난 역할을 맡으면 상대를 마음껏 탓해도 돼요.","answer":"X","reason_options":[{"t":"놀이에서도 「나」로 시작해 바르고 고운 말로 기분을 말하니까","correct":true},{"t":"놀이는 진짜가 아니니까","mis":"K1-2-u1-X09"}],"mis":"K1-2-u1-X09","explanation":["놀이에서도 바르고 고운 말을 써요.","화난 역할도 「나는 ○○해서 화가 났어」로 말해요.","역할놀이는 말하는 방법을 연습하는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#9','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',2,'blank','auto','역할놀이예요. 늦게 온 친구에게 말해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#10','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',3,'error','auto','역할놀이 대본이에요. 「나」의 말에서 고칠 것은 무엇인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"역할놀이 대본이에요. 「나」의 말에서 고칠 것은 무엇인가요?","options":[{"t":"「나는 오래 기다려서 걱정했어」처럼 「나」로 시작해 있었던 일과 기분을 말해요","correct":true,"mis_target":"K1-2-u1-X09"},{"t":"더 화난 목소리로 말해요","mis":"K1-2-u1-X11"},{"t":"아무 말도 하지 않아요","mis":"K1-2-u1-X11"}],"explanation":["「넌 왜 맨날」은 탓하는 말이에요.","화난 목소리나 침묵은 마음을 전하지 못해요.","첫 낱말을 「나」로 바꾸고 기다리며 든 마음을 넣어요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"미안해, 늦었어."},{"who":"나","text":"넌 왜 맨날 늦어! 짜증 나!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#1','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',2,'mc','auto','친구의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X10']::text[],true,'{"seq":1,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"친구의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"나는 공을 찾으러 가야 해서 속상했어. 다음엔 조심해 줘.","correct":true},{"t":"너 진짜 왜 그래!","mis":"K1-2-u1-X09"},{"t":"됐어. 다신 안 놀아.","mis":"K1-2-u1-X10"}],"explanation":["있었던 일과 기분을 말하고, 바라는 것도 덧붙였어요.","「왜 그래」는 탓하는 말, 「안 놀아」는 밀어내는 말이에요.","친구가 먼저 사과했으니 내 마음을 차분히 말해요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"네 공을 내가 멀리 차 버렸어. 미안."},{"who":"나","text":"…"}]},"variant_rule":{"alt":[{"stem":"친구의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"나는 내 그림이 찢어져서 속상했어. 다음엔 물어봐 줘.","correct":true},{"t":"너 진짜 나빠!","mis":"K1-2-u1-X09"},{"t":"됐어. 너랑 말 안 해.","mis":"K1-2-u1-X10"}],"explanation":["있었던 일과 기분, 바라는 것을 말했어요.","「나빠」는 탓, 「말 안 해」는 밀어내는 말이에요.","사과한 친구에게 내 마음을 알려 줘요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"네 그림을 실수로 찢었어. 미안해."},{"who":"나","text":"…"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#2','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C4',2,'mc','auto','역할놀이예요. 동생이 내가 쌓은 블록을 무너뜨렸어요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":2,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"역할놀이예요. 동생이 내가 쌓은 블록을 무너뜨렸어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"속상해요","correct":true},{"t":"편안해요","mis":"K1-2-u1-X07"},{"t":"반가워요","mis":"K1-2-u1-X07"}],"explanation":["열심히 쌓은 것이 무너지면 속상해요.","편안하거나 반가운 일이 아니에요.","무너진 블록 앞에 선 나를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#3','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',3,'match','auto','상황과 그때 할 수 있는 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"K1-2-u1-C5","difficulty":3,"kind":"match","stem":"상황과 그때 할 수 있는 말을 선으로 이어 보세요.","pairs":[{"l":"짝이 연필을 빌려주었어요","r":"나는 빌려 줘서 고마워."},{"l":"친구가 내 별명을 부르며 놀렸어요","r":"나는 별명으로 불려서 속상해."},{"l":"동생이 먼저 사과했어요","r":"나는 사과해 줘서 마음이 풀렸어."},{"l":"우리 편이 함께 이겼어요","r":"나는 같이 이겨서 신나."}],"mis":"K1-2-u1-X10","explanation":["상황마다 있었던 일이 다르고 기분도 달라요.","고마워·속상해·풀렸어·신나 — 모두 「나」로 시작해요.","「○○해서」를 상황과 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#4','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',3,'mc','auto','역할놀이 차례예요. 세 번째로 할 일은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#5','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',3,'error','auto','역할놀이 대본이에요. 「나」의 말은 「나」로 시작했는데 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":5,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"역할놀이 대본이에요. 「나」의 말은 「나」로 시작했는데 무엇이 잘못되었나요?","options":[{"t":"있었던 일과 기분 대신 상대를 탓하는 말을 넣었어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」을 빼야 해요","mis":"K1-2-u1-X09"},{"t":"더 크게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["「네가 싫어」는 탓하는 말이에요.","「나는 내 차례를 못 해서 답답했어」처럼 일과 기분을 넣어요.","「나」 뒤에 무엇이 오는지 봐요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"내가 먼저 할게!"},{"who":"나","text":"나는 네가 싫어!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#6','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',3,'ox','auto','친구가 힘들어할 때는 내 기분보다 친구 마음을 알아주는 말이 먼저예요.',ARRAY['K1-2-u1-X12']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":3,"kind":"ox","stem":"친구가 힘들어할 때는 내 기분보다 친구 마음을 알아주는 말이 먼저예요.","answer":"O","reason_options":[{"t":"마음을 알아주는 말이 힘이 되니까","correct":true},{"t":"힘든 친구는 그냥 두는 게 좋으니까","mis":"K1-2-u1-X12"}],"mis":"K1-2-u1-X12","explanation":["「나도 떨렸어. 나는 네가 잘할 것 같아」처럼 마음을 알아줘요.","그냥 두면 친구가 더 외로워요.","내가 힘들 때 듣고 싶은 말을 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#7','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',3,'mc','auto','친구의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X12']::text[],false,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"친구의 말을 듣고 내가 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"나도 그런 적 있어. 나는 네가 다음엔 잘할 것 같아.","correct":true},{"t":"그러게 연습 좀 하지.","mis":"K1-2-u1-X09"},{"t":"나는 잘했는데.","mis":"K1-2-u1-X12"}],"explanation":["마음을 알아주고 힘을 주는 말이에요.","「연습 좀 하지」는 탓하는 말이고, 「나는 잘했는데」는 친구 마음을 살피지 않아요.","힘든 친구에게는 내 이야기보다 친구 마음이 먼저예요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"나 오늘 발표 망쳤어…"},{"who":"나","text":"…"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#8','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',4,'sa','auto','역할놀이예요. 발표 차례가 바로 다음이에요. 「나는 발표가 다가와서 ○○○.」의 빈칸에 들어갈 기분 말을 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u1-C5","difficulty":4,"kind":"sa","stem":"역할놀이예요. 발표 차례가 바로 다음이에요. 「나는 발표가 다가와서 ○○○.」의 빈칸에 들어갈 기분 말을 쓰세요.","answer":["떨려요","떨려","떨렸어요","떨렸어","떨린다","떨림","긴장돼요","긴장했어요","긴장해요","긴장","설레요","설레","두근두근","콩닥콩닥","두근거려요","조마조마","조마조마해요","걱정돼요","걱정돼"],"explanation":["발표를 앞두면 가슴이 뛰고 떨려요.","편안하거나 심심한 마음이 아니에요.","앞에 나가기 직전을 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"역할놀이예요. 친구가 내 우산을 같이 씌워 주었어요. 「나는 우산을 씌워 줘서 ○○○.」의 빈칸에 들어갈 기분 말을 쓰세요.","answer":["고마워요","고마워","고맙다","고마웠어요","고마웠어","고마움","고맙습니다","감사해요","감사","기뻐요","기뻐","기뻤어요","든든해요","든든해"],"explanation":["나를 챙겨 주면 고마운 마음이 들어요.","아쉽거나 지루한 일이 아니에요.","우산 속에 함께 선 나를 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#9','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','실수로 친구 옷을 적신 상황이에요. 역할놀이 대본을 두 줄로 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#10','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','친구가 넘어져서 아파하고 있어요. 친구 마음을 알아주는 말을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"친구가 넘어져서 아파하고 있어요. 친구 마음을 알아주는 말을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 나는 네가 다쳐서 걱정돼. 많이 아프지? / 나도 넘어져 봤어. 나는 네가 금방 나을 것 같아. — 친구 마음을 살피는 말이면 맞아요.","scoring_points":["친구 마음을 알아주는 말인가","놀리거나 탓하는 말이 없는가","한 문장으로 썼는가"]},"explanation":["친구가 힘들 때는 마음을 알아주는 말이 먼저예요.","「그러게 조심하지」는 탓하는 말이라 힘이 안 돼요.","내가 넘어졌을 때 듣고 싶은 말을 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#1','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C1',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],false,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"짹짹","correct":true},{"t":"아장아장","mis":"K1-2-u1-X02"},{"t":"데굴데굴","mis":"K1-2-u1-X02"}],"explanation":["짹짹은(는) 새가 우는 소리를 그대로 옮긴 말이에요.","나머지는 눈으로 본 모양을 옮긴 말이에요.","입으로 내 보고 귀로 들리는 것인지 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#2','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C1',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],false,'{"seq":2,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"아장아장","correct":true},{"t":"개굴개굴","mis":"K1-2-u1-X02"},{"t":"꼬르륵","mis":"K1-2-u1-X02"}],"explanation":["아장아장은(는) 아기가 걷는 모양을 옮긴 말이에요.","나머지는 귀로 들은 소리를 옮긴 말이에요.","몸으로 따라 할 수 있으면 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#3','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C4',1,'mc','auto','다음 가운데 기분을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u1-X08']::text[],false,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"다음 가운데 기분을 나타내는 말은 어느 것인가요?","options":[{"t":"신나요","correct":true},{"t":"우산","mis":"K1-2-u1-X08"},{"t":"교실","mis":"K1-2-u1-X08"}],"explanation":["신나요는 마음이 어떠한지 알려 주는 말이에요.","우산은 물건, 교실은 장소예요.","「마음이 ○○해요」로 바꿔 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#4','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C4',1,'mc','auto','친구가 무거운 짐을 들어 주었어요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"친구가 무거운 짐을 들어 주었어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"고마워요","correct":true},{"t":"화나요","mis":"K1-2-u1-X07"},{"t":"무서워요","mis":"K1-2-u1-X07"}],"explanation":["도움을 받으면 고마운 마음이 들어요.","화나거나 무서운 일이 아니에요.","그 자리의 나를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#5','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C2',1,'blank','auto','빈칸에 알맞은 흉내 내는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#6','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C5',1,'mc','auto','듣는 사람을 생각한 말은 어느 것인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X10']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"듣는 사람을 생각한 말은 어느 것인가요?","options":[{"t":"나는 그림이 지워져서 속상했어.","correct":true},{"t":"너 때문에 다 망쳤잖아!","mis":"K1-2-u1-X09"},{"t":"다 망쳤어. 됐어.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말했어요.","「너 때문에」는 탓하는 말, 「됐어」는 기분이 안 보여요.","첫 낱말을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#7','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C6',1,'mc','auto','다람쥐가 무엇을 할까요? 알맞은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":7,"concept":"K1-2-u1-C6","difficulty":1,"kind":"mc","stem":"다람쥐가 무엇을 할까요? 알맞은 문장은 어느 것인가요?","options":[{"t":"다람쥐가 도토리를 먹습니다.","correct":true},{"t":"도토리가 다람쥐를 먹습니다.","mis":"K1-2-u1-X13"},{"t":"다람쥐가 도토리를 마십니다.","mis":"K1-2-u1-X14"}],"explanation":["누가(다람쥐가) 무엇을(도토리를) 어찌하다(먹습니다) 차례로 이어요.","도토리는 먹을 수 없고, 도토리를 마실 수도 없어요.","그림을 보고 「누가 하는 일인지」 짚어 봐요."],"asset":{"type":"scene","icon":"🐿️🌰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#8','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C3',1,'mc','auto','「콩닥콩닥」이 나타내는 마음은 어느 것인가요?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「콩닥콩닥」이 나타내는 마음은 어느 것인가요?","options":[{"t":"떨려요","correct":true},{"t":"졸려요","mis":"K1-2-u1-X06"},{"t":"편안해요","mis":"K1-2-u1-X06"}],"explanation":["콩닥콩닥은 가슴이 뛰는 떨리는 마음이에요.","졸리거나 편안할 때는 가슴이 뛰지 않아요.","발표 앞에 선 나를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#9','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C1',2,'match','auto','그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C1","difficulty":2,"kind":"match","stem":"그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.","pairs":[{"l":"🐸 개구리","r":"개굴개굴"},{"l":"❄️ 쌓인 눈","r":"소복소복"},{"l":"✏️ 연필 소리","r":"사각사각"}],"mis":"K1-2-u1-X03","explanation":["개구리는 개굴개굴, 눈은 소복소복이에요.","연필은 사각사각 소리가 나요.","그림마다 소리나 모양을 먼저 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#10','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C2',2,'mc','auto','눈 쌓이는 모습이 눈앞에 보이는 것 같은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X04','K1-2-u1-X03']::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"눈 쌓이는 모습이 눈앞에 보이는 것 같은 문장은 어느 것인가요?","options":[{"t":"눈이 소복소복 쌓였어요.","correct":true},{"t":"눈이 쌓였어요.","mis":"K1-2-u1-X04"},{"t":"눈이 꼬르륵 쌓였어요.","mis":"K1-2-u1-X03"}],"explanation":["소복소복은 눈이 쌓이는 모양이에요.","흉내 내는 말이 없으면 안 떠오르고, 꼬르륵은 어울리지 않아요.","어울리는 흉내 내는 말이 있어야 실감 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
