INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#12','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C4',2,'match','auto','장면과 그때 드는 기분을 선으로 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K1-2-u1-C4","difficulty":2,"kind":"match","stem":"장면과 그때 드는 기분을 선으로 이어 보세요.","pairs":[{"l":"상을 받았어요","r":"뿌듯해요"},{"l":"친구가 못 왔어요","r":"아쉬워요"},{"l":"깜깜한 방에 혼자 있어요","r":"무서워요"}],"mis":"K1-2-u1-X07","explanation":["상을 받으면 뿌듯하고, 친구가 못 오면 아쉬워요.","깜깜한 곳에 혼자면 무서워요.","「나라면」 하고 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
