INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#16','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C3',2,'ox','auto','마음도 흉내 내는 말로 나타낼 수 있어요.',ARRAY['K1-2-u1-X05']::text[],false,'{"seq":16,"concept":"K1-2-u1-C3","difficulty":2,"kind":"ox","stem":"마음도 흉내 내는 말로 나타낼 수 있어요.","answer":"O","reason_options":[{"t":"콩닥콩닥처럼 마음속 느낌을 옮길 수 있으니까","correct":true},{"t":"흉내 내는 말은 물건 소리에만 쓰니까","mis":"K1-2-u1-X05"}],"mis":"K1-2-u1-X05","explanation":["흉내 내는 말은 마음도 실감 나게 나타내요.","물건 소리에만 쓰는 게 아니에요.","기쁠 때 마음속을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
