INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#18','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C2',3,'error','auto','「눈이 꼬르륵 쌓였어요.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],false,'{"seq":18,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「눈이 꼬르륵 쌓였어요.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"꼬르륵은 배에서 나는 소리라 눈이 쌓이는 장면과 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"눈에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「쌓였어요」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["눈이 쌓이는 모양은 소복소복이에요.","꼬르륵은 배가 고플 때 나는 소리예요.","장면을 먼저 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#19','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C4',3,'ox','auto','같은 일을 겪어도 사람마다 느끼는 기분이 다를 수 있어요.',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":19,"concept":"K1-2-u1-C4","difficulty":3,"kind":"ox","stem":"같은 일을 겪어도 사람마다 느끼는 기분이 다를 수 있어요.","answer":"O","reason_options":[{"t":"비 오는 날 좋아하는 친구도 아쉬워하는 친구도 있으니까","correct":true},{"t":"같은 일이면 기분도 꼭 같아야 하니까","mis":"K1-2-u1-X07"}],"mis":"K1-2-u1-X07","explanation":["같은 일이라도 사람마다 기분은 달라요.","기분에는 맞고 틀린 것이 없어요.","내 기분을 말로 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#20','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C5',3,'mc','auto','「그네 앞에서」를 읽고 답하세요. 친구의 얼굴이 굳은 까닭은 무엇인가요?',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":20,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"「그네 앞에서」를 읽고 답하세요. 친구의 얼굴이 굳은 까닭은 무엇인가요?","options":[{"t":"탓하는 큰 소리를 들어서","correct":true},{"t":"그네가 너무 낮아서","mis":"K1-2-u1-X09"},{"t":"비가 내려서","mis":"K1-2-u1-X09"}],"explanation":["「너는 왜 새치기를 하니!」라는 말을 들어서예요.","그네나 비 때문이 아니에요.","두 번째 줄과 세 번째 줄을 이어 읽어요."],"asset":{"type":"passage","lines":["그네를 타려고 한참 기다렸는데 다른 친구가 먼저 앉았어요.","나도 모르게 큰 소리가 나왔어요. \"너는 왜 새치기를 하니!\"","그 말을 들은 친구의 얼굴이 굳었어요. 마음이 편하지 않았어요.","숨을 한 번 쉬고 다시 말했어요. \"나는 오래 기다려서 마음이 급했어.\"","친구가 웃으며 말했어요. \"몰랐어. 열까지 세고 바꿔 탈까?\""],"title":"그네 앞에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#21','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C5',3,'error','auto','「나는 네가 정말 미워.」 이 말은 「나」로 시작했는데 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":21,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 네가 정말 미워.」 이 말은 「나」로 시작했는데 무엇이 잘못되었나요?","options":[{"t":"있었던 일과 내 기분 대신 상대를 탓하는 말을 넣었어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」을 「너는」으로 바꿔야 해요","mis":"K1-2-u1-X09"},{"t":"더 짧게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["「네가 미워」는 탓하는 말이에요.","「나는 약속을 어겨서 속상했어」처럼 일과 기분을 넣어요.","두 칸이 다 있는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#22','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C6',3,'error','auto','「도토리가 다람쥐를 먹습니다.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":22,"concept":"K1-2-u1-C6","difficulty":3,"kind":"error","stem":"「도토리가 다람쥐를 먹습니다.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"누가와 무엇을 자리가 바뀌었어요 — 다람쥐가 도토리를 먹습니다","correct":true,"mis_target":"K1-2-u1-X13"},{"t":"「먹습니다」가 잘못이에요","mis":"K1-2-u1-X14"},{"t":"「도토리」를 빼야 해요","mis":"K1-2-u1-X13"}],"explanation":["먹는 것은 다람쥐예요.","누가(다람쥐가) 무엇을(도토리를) 어찌하다(먹습니다) 차례로 고쳐요.","누가 하는 일인지 손가락으로 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#23','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C3',4,'sa','auto','「마음이 콩닥콩닥 뛰었어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u1-C3","difficulty":4,"kind":"sa","stem":"「마음이 콩닥콩닥 뛰었어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.","answer":["떨려요","떨려","떨렸어요","떨렸어","떨린다","떨림","설레요","설레","설렜어요","설렘","긴장","긴장돼요","긴장했어요","긴장해요","두근두근","두근거려요"],"explanation":["콩닥콩닥은 떨리는 마음이에요.","화나거나 졸린 마음이 아니에요.","발표 앞의 나를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#24','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C5',4,'essay','teacher','「너는 왜 새치기를 하니!」를 「나」로 시작하는 말로 바꿔 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"「너는 왜 새치기를 하니!」를 「나」로 시작하는 말로 바꿔 쓰세요.","answer_guide":{"answer":"예: 나는 오래 기다려서 마음이 급했어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","탓하는 말 대신 내가 겪은 일을 말해요.","「그네 앞에서」 네 번째 줄이 본보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#25','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C2',4,'essay','teacher','「비가 내려요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"「비가 내려요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.","answer_guide":{"answer":"예: 비가 주룩주룩 내려요. / 비가 부슬부슬 내려요. — 비와 어울리는 흉내 내는 말이면 맞아요.","scoring_points":["흉내 내는 말이 들어갔는가","비와 어울리는가","문장이 자연스러운가"]},"explanation":["주룩주룩·부슬부슬처럼 비 오는 소리나 모양을 넣어요.","꼬르륵처럼 상관없는 소리는 어긋나요.","창밖의 비를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#1','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C1',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],false,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"멍멍","correct":true},{"t":"훨훨","mis":"K1-2-u1-X02"},{"t":"뭉게뭉게","mis":"K1-2-u1-X02"}],"explanation":["멍멍은(는) 강아지가 짖는 소리를 그대로 옮긴 말이에요.","나머지는 눈으로 본 모양을 옮긴 말이에요.","입으로 내 보고 귀로 들리는 것인지 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#2','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C1',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],false,'{"seq":2,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"뭉게뭉게","correct":true},{"t":"야옹","mis":"K1-2-u1-X02"},{"t":"똑똑","mis":"K1-2-u1-X02"}],"explanation":["뭉게뭉게은(는) 구름이 피어오르는 모양을 옮긴 말이에요.","나머지는 귀로 들은 소리를 옮긴 말이에요.","몸으로 따라 할 수 있으면 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#3','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C4',1,'mc','auto','다음 가운데 기분을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u1-X08']::text[],false,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"다음 가운데 기분을 나타내는 말은 어느 것인가요?","options":[{"t":"서운해요","correct":true},{"t":"책상","mis":"K1-2-u1-X08"},{"t":"달리기","mis":"K1-2-u1-X08"}],"explanation":["서운해요는 마음을 나타내는 말이에요.","책상은 물건, 달리기는 하는 일이에요.","「마음이 ○○해요」로 바꿔 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#4','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C4',1,'mc','auto','아끼던 컵이 깨졌어요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"아끼던 컵이 깨졌어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"속상해요","correct":true},{"t":"즐거워요","mis":"K1-2-u1-X07"},{"t":"궁금해요","mis":"K1-2-u1-X07"}],"explanation":["아끼던 것이 깨지면 속상한 마음이 들어요.","즐겁거나 궁금한 일이 아니에요.","깨진 컵 앞에 선 나를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#5','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C2',1,'blank','auto','빈칸에 알맞은 흉내 내는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#6','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C5',1,'mc','auto','듣는 사람을 생각한 말은 어느 것인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X10']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"듣는 사람을 생각한 말은 어느 것인가요?","options":[{"t":"나는 혼자 남아서 서운했어.","correct":true},{"t":"너희 다 미워!","mis":"K1-2-u1-X09"},{"t":"됐어, 몰라.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말했어요.","「미워」는 탓하는 말, 「몰라」는 기분이 안 보여요.","「나는 ○○해서 ○○했어」 틀을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#7','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C6',1,'mc','auto','아이가 무엇을 할까요? 알맞은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":7,"concept":"K1-2-u1-C6","difficulty":1,"kind":"mc","stem":"아이가 무엇을 할까요? 알맞은 문장은 어느 것인가요?","options":[{"t":"아이가 우산을 씁니다.","correct":true},{"t":"우산이 아이를 씁니다.","mis":"K1-2-u1-X13"},{"t":"아이가 우산을 마십니다.","mis":"K1-2-u1-X14"}],"explanation":["누가(아이가) 무엇을(우산을) 어찌하다(씁니다) 차례예요.","우산이 아이를 쓸 수 없고, 우산을 마실 수도 없어요.","비 오는 날 하는 일을 떠올려 봐요."],"asset":{"type":"scene","icon":"☔🧒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#8','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C3',1,'mc','auto','「부글부글」이 나타내는 마음은 어느 것인가요?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「부글부글」이 나타내는 마음은 어느 것인가요?","options":[{"t":"화나요","correct":true},{"t":"신나요","mis":"K1-2-u1-X06"},{"t":"졸려요","mis":"K1-2-u1-X06"}],"explanation":["부글부글은 속이 끓는 화난 마음이에요.","신나거나 졸린 마음과는 달라요.","끓는 물을 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#9','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C1',2,'match','auto','그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C1","difficulty":2,"kind":"match","stem":"그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.","pairs":[{"l":"🐶 강아지","r":"멍멍"},{"l":"🌧️ 가는 비","r":"부슬부슬"},{"l":"🔔 종","r":"딸랑딸랑"}],"mis":"K1-2-u1-X03","explanation":["강아지는 멍멍, 가는 비는 부슬부슬이에요.","종은 딸랑딸랑 울려요.","그림을 보고 소리를 내 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#10','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C2',2,'mc','auto','비 오는 소리가 들리는 것 같은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X04','K1-2-u1-X03']::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"비 오는 소리가 들리는 것 같은 문장은 어느 것인가요?","options":[{"t":"비가 주룩주룩 내려요.","correct":true},{"t":"비가 내려요.","mis":"K1-2-u1-X04"},{"t":"비가 아삭아삭 내려요.","mis":"K1-2-u1-X03"}],"explanation":["주룩주룩은 비 오는 소리예요.","흉내 내는 말이 없으면 소리가 안 들리고, 아삭아삭은 어울리지 않아요.","소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
