INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#12','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C4',2,'match','auto','장면과 그때 드는 기분을 선으로 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K1-2-u1-C4","difficulty":2,"kind":"match","stem":"장면과 그때 드는 기분을 선으로 이어 보세요.","pairs":[{"l":"선물을 받았어요","r":"고마워요"},{"l":"처음으로 발표해요","r":"떨려요"},{"l":"아끼던 컵이 깨졌어요","r":"속상해요"}],"mis":"K1-2-u1-X07","explanation":["선물을 받으면 고맙고, 처음 발표하면 떨려요.","아끼던 것이 깨지면 속상해요.","장면을 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
