INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#14','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C5',2,'mc','auto','듣는 사람을 생각하며 말하는 차례에서 마지막 걸음은 무엇인가요?',ARRAY['K1-2-u1-X11','K1-2-u1-X09']::text[],false,'{"seq":14,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"듣는 사람을 생각하며 말하는 차례에서 마지막 걸음은 무엇인가요?","options":[{"t":"「나」로 시작해 있었던 일과 기분을 말하기","correct":true},{"t":"큰 소리로 세 번 말하기","mis":"K1-2-u1-X11"},{"t":"친구 잘못을 세어 보기","mis":"K1-2-u1-X09"}],"explanation":["마지막에는 「나」로 시작해 일과 기분을 말해요.","큰 소리나 잘못 세기는 차례에 없어요.","① 무슨 일 ② 내 기분 ③ 듣는 사람 ④ 나로 말하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
