INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#16','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C3',2,'ox','auto','「부글부글」은 신나는 마음을 나타내요.',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":16,"concept":"K1-2-u1-C3","difficulty":2,"kind":"ox","stem":"「부글부글」은 신나는 마음을 나타내요.","answer":"X","reason_options":[{"t":"속이 끓는 화난 마음을 나타내니까","correct":true},{"t":"부글부글은 즐거운 소리니까","mis":"K1-2-u1-X06"}],"mis":"K1-2-u1-X06","explanation":["부글부글은 화난 마음이에요.","신나는 마음은 훨훨이나 둥실둥실이에요.","「오늘 내 마음」 세 번째 줄을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
