INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#18','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C2',3,'error','auto','「강아지가 아삭아삭 짖어요.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],false,'{"seq":18,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「강아지가 아삭아삭 짖어요.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"아삭아삭은 씹는 소리라 강아지가 짖는 장면과 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"강아지에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「짖어요」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["강아지가 짖는 소리는 멍멍이에요.","아삭아삭은 사과를 씹는 소리예요.","장면을 먼저 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#19','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C4',3,'ox','auto','기분을 나타내는 말은 기뻐요와 슬퍼요 두 가지뿐이에요.',ARRAY['K1-2-u1-X08']::text[],false,'{"seq":19,"concept":"K1-2-u1-C4","difficulty":3,"kind":"ox","stem":"기분을 나타내는 말은 기뻐요와 슬퍼요 두 가지뿐이에요.","answer":"X","reason_options":[{"t":"반가워요·뿌듯해요·서운해요처럼 아주 많으니까","correct":true},{"t":"기분은 좋은 것과 나쁜 것 둘뿐이니까","mis":"K1-2-u1-X08"}],"mis":"K1-2-u1-X08","explanation":["기분을 나타내는 말은 아주 많아요.","내 마음에 꼭 맞는 말을 찾을수록 마음이 잘 전해져요.","반갑고 뿌듯하고 서운한 마음을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#20','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C5',3,'mc','auto','「빌려준 색연필」을 읽고 답하세요. 짝이 고개를 푹 숙인 까닭은 무엇인가요?',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":20,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"「빌려준 색연필」을 읽고 답하세요. 짝이 고개를 푹 숙인 까닭은 무엇인가요?","options":[{"t":"탓하는 말을 듣고 마음이 상해서","correct":true},{"t":"색연필이 너무 무거워서","mis":"K1-2-u1-X09"},{"t":"잠이 와서","mis":"K1-2-u1-X09"}],"explanation":["「너는 왜 남의 걸 함부로 써!」라는 말을 들어서예요.","색연필이나 잠 때문이 아니에요.","두 번째 줄과 세 번째 줄을 이어 읽어요."],"asset":{"type":"passage","lines":["짝이 내 색연필을 빌려 가서 부러뜨렸어요.","나는 \"너는 왜 남의 걸 함부로 써!\" 하고 소리쳤어요.","짝은 고개를 푹 숙였어요.","나는 다시 말했어요. \"나는 아끼던 색연필이 부러져서 속상했어.\"","짝이 말했어요. \"미안해. 내가 새것으로 사 줄게.\""],"title":"빌려준 색연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#21','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C5',3,'error','auto','「나는 너 같은 애랑 안 놀아.」 이 말은 「나」로 시작했는데 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":21,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 너 같은 애랑 안 놀아.」 이 말은 「나」로 시작했는데 무엇이 잘못되었나요?","options":[{"t":"있었던 일과 내 기분 대신 상대를 밀어내는 말을 넣었어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」을 빼야 해요","mis":"K1-2-u1-X09"},{"t":"더 크게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["상대를 밀어내는 말이면 마음이 전해지지 않아요.","「나는 놀이에 끼지 못해서 서운했어」처럼 말해요.","두 칸을 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#22','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C6',3,'error','auto','「우산이 아이를 씁니다.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":22,"concept":"K1-2-u1-C6","difficulty":3,"kind":"error","stem":"「우산이 아이를 씁니다.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"누가와 무엇을 자리가 바뀌었어요 — 아이가 우산을 씁니다","correct":true,"mis_target":"K1-2-u1-X13"},{"t":"「씁니다」가 잘못이에요","mis":"K1-2-u1-X14"},{"t":"「아이」를 빼야 해요","mis":"K1-2-u1-X13"}],"explanation":["우산을 쓰는 것은 아이예요.","누가(아이가) 무엇을(우산을) 어찌하다(씁니다) 차례로 고쳐요.","누가 하는 일인지 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#23','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C3',4,'sa','auto','「마음이 부글부글 끓었어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u1-C3","difficulty":4,"kind":"sa","stem":"「마음이 부글부글 끓었어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.","answer":["화나요","화나","화났어요","화났어","화가나요","화가났어요","화","화남","화가난다","화난다","화가났다","속상해요","속상해","속상했어요","짜증나요","짜증"],"explanation":["부글부글은 화난 마음이에요.","신나거나 편안한 마음이 아니에요.","끓는 냄비를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#24','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C5',4,'essay','teacher','「너는 왜 남의 걸 함부로 써!」를 「나」로 시작하는 말로 바꿔 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"「너는 왜 남의 걸 함부로 써!」를 「나」로 시작하는 말로 바꿔 쓰세요.","answer_guide":{"answer":"예: 나는 아끼던 색연필이 부러져서 속상했어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","탓하는 말 대신 내가 겪은 일을 말해요.","「빌려준 색연필」 네 번째 줄이 본보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#25','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C2',4,'essay','teacher','「강아지가 달려와요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"「강아지가 달려와요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.","answer_guide":{"answer":"예: 강아지가 총총 달려와요. / 강아지가 멍멍 짖으며 달려와요. — 달려오는 모습·소리에 어울리면 맞아요.","scoring_points":["흉내 내는 말이 들어갔는가","달려오는 장면과 어울리는가","문장이 자연스러운가"]},"explanation":["총총·후다닥처럼 달려오는 모양을 넣어요.","소복소복처럼 어울리지 않는 말은 어긋나요.","달려오는 모습을 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#1','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C1',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],false,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"후루룩","correct":true},{"t":"반짝반짝","mis":"K1-2-u1-X02"},{"t":"살금살금","mis":"K1-2-u1-X02"}],"explanation":["후루룩은(는) 국수를 먹는 소리를 그대로 옮긴 말이에요.","나머지는 눈으로 본 모양을 옮긴 말이에요.","입으로 내 보고 귀로 들리는 것인지 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#2','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C1',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],false,'{"seq":2,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"데굴데굴","correct":true},{"t":"쨍그랑","mis":"K1-2-u1-X02"},{"t":"보글보글","mis":"K1-2-u1-X02"}],"explanation":["데굴데굴은(는) 공이 구르는 모양을 옮긴 말이에요.","나머지는 귀로 들은 소리를 옮긴 말이에요.","몸으로 따라 할 수 있으면 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#3','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C4',1,'mc','auto','다음 가운데 기분을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u1-X08']::text[],false,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"다음 가운데 기분을 나타내는 말은 어느 것인가요?","options":[{"t":"뿌듯해요","correct":true},{"t":"필통","mis":"K1-2-u1-X08"},{"t":"운동장","mis":"K1-2-u1-X08"}],"explanation":["뿌듯해요는 마음을 나타내는 말이에요.","필통은 물건, 운동장은 장소예요.","「마음이 ○○해요」로 바꿔 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#4','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C4',1,'mc','auto','오래 기다린 소풍날 아침이에요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"오래 기다린 소풍날 아침이에요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"신나요","correct":true},{"t":"지루해요","mis":"K1-2-u1-X07"},{"t":"무서워요","mis":"K1-2-u1-X07"}],"explanation":["기다리던 일이 다가오면 설레고 신나요.","지루하거나 무서운 일이 아니에요.","가방을 메는 나를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
