INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#6','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C5',1,'mc','auto','듣는 사람을 생각한 말은 어느 것인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X10']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"듣는 사람을 생각한 말은 어느 것인가요?","options":[{"t":"나는 기다려 줘서 고마웠어.","correct":true},{"t":"너 진짜 느리다.","mis":"K1-2-u1-X09"},{"t":"그냥 뭐, 됐어.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 고마운 마음을 말했어요.","「느리다」는 놀리는 말, 「됐어」는 기분이 없어요.","좋은 기분도 같은 틀로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#7','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C6',1,'mc','auto','고양이가 무엇을 할까요? 알맞은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":7,"concept":"K1-2-u1-C6","difficulty":1,"kind":"mc","stem":"고양이가 무엇을 할까요? 알맞은 문장은 어느 것인가요?","options":[{"t":"고양이가 우유를 마십니다.","correct":true},{"t":"우유가 고양이를 마십니다.","mis":"K1-2-u1-X13"},{"t":"고양이가 우유를 입습니다.","mis":"K1-2-u1-X14"}],"explanation":["누가(고양이가) 무엇을(우유를) 어찌하다(마십니다) 차례예요.","우유가 고양이를 마실 수 없고, 우유를 입을 수도 없어요.","고양이가 하는 일을 떠올려 봐요."],"asset":{"type":"scene","icon":"🐈🥛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#8','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C3',1,'mc','auto','「사르르」가 나타내는 마음은 어느 것인가요?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「사르르」가 나타내는 마음은 어느 것인가요?","options":[{"t":"마음이 풀려요","correct":true},{"t":"무서워요","mis":"K1-2-u1-X06"},{"t":"화나요","mis":"K1-2-u1-X06"}],"explanation":["사르르는 굳었던 마음이 풀리는 것이에요.","무섭거나 화나는 마음과는 반대예요.","눈이 녹는 모습을 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#9','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C1',2,'match','auto','그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C1","difficulty":2,"kind":"match","stem":"그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.","pairs":[{"l":"🐥 병아리","r":"삐악삐악"},{"l":"⚽ 굴러가는 공","r":"데굴데굴"},{"l":"🦋 나비","r":"훨훨"}],"mis":"K1-2-u1-X03","explanation":["병아리는 삐악삐악, 공은 데굴데굴이에요.","나비는 훨훨 날아요.","소리인지 모양인지 나눠 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#10','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C2',2,'mc','auto','강아지가 꼬리를 흔드는 모습이 보이는 것 같은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X04','K1-2-u1-X03']::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"강아지가 꼬리를 흔드는 모습이 보이는 것 같은 문장은 어느 것인가요?","options":[{"t":"강아지가 꼬리를 살랑살랑 흔들어요.","correct":true},{"t":"강아지가 꼬리를 흔들어요.","mis":"K1-2-u1-X04"},{"t":"강아지가 꼬리를 쨍그랑 흔들어요.","mis":"K1-2-u1-X03"}],"explanation":["살랑살랑은 가볍게 흔드는 모양이에요.","흉내 내는 말이 없으면 모습이 안 떠오르고, 쨍그랑은 어울리지 않아요.","꼬리를 흔드는 모습을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#11','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C3',2,'blank','auto','빈칸에 알맞은 흉내 내는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#12','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C4',2,'match','auto','장면과 그때 드는 기분을 선으로 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K1-2-u1-C4","difficulty":2,"kind":"match","stem":"장면과 그때 드는 기분을 선으로 이어 보세요.","pairs":[{"l":"넘어진 나를 일으켜 주었어요","r":"고마워요"},{"l":"소풍이 미루어졌어요","r":"아쉬워요"},{"l":"혼자 힘으로 해냈어요","r":"뿌듯해요"}],"mis":"K1-2-u1-X07","explanation":["도움을 받으면 고맙고, 미루어지면 아쉬워요.","혼자 해내면 뿌듯해요.","하나씩 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
