INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#14','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C5',2,'mc','auto','듣는 사람을 생각하며 말할 때 생각할 것이 아닌 것은 어느 것인가요?',ARRAY['K1-2-u1-X11']::text[],false,'{"seq":14,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"듣는 사람을 생각하며 말할 때 생각할 것이 아닌 것은 어느 것인가요?","options":[{"t":"내 목소리를 제일 크게 하기","correct":true},{"t":"무슨 일이 있었는지","mis":"K1-2-u1-X11"},{"t":"듣는 사람의 기분","mis":"K1-2-u1-X11"}],"explanation":["목소리 크기는 생각할 일이 아니에요.","있었던 일과 듣는 사람 기분은 꼭 생각해요.","네 걸음 가운데 없는 것을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
