INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#16','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C3',2,'ox','auto','「사르르」는 화가 난 마음을 나타내요.',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":16,"concept":"K1-2-u1-C3","difficulty":2,"kind":"ox","stem":"「사르르」는 화가 난 마음을 나타내요.","answer":"X","reason_options":[{"t":"굳은 마음이 부드럽게 풀리는 것을 나타내니까","correct":true},{"t":"사르르는 무섭게 들리니까","mis":"K1-2-u1-X06"}],"mis":"K1-2-u1-X06","explanation":["사르르는 마음이 풀리는 것이에요.","화난 마음은 부글부글이에요.","눈이 녹는 모습을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
