INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#18','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C2',3,'error','auto','「나비가 데굴데굴 날아가요.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],false,'{"seq":18,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「나비가 데굴데굴 날아가요.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"데굴데굴은 구르는 모양이라 나비가 나는 장면과 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"나비에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「날아가요」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["나비가 나는 모양은 훨훨이에요.","데굴데굴은 공이 구르는 모양이에요.","장면을 먼저 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#19','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C4',3,'ox','auto','기분을 나타내는 말은 좋은 기분에만 써요.',ARRAY['K1-2-u1-X12']::text[],false,'{"seq":19,"concept":"K1-2-u1-C4","difficulty":3,"kind":"ox","stem":"기분을 나타내는 말은 좋은 기분에만 써요.","answer":"X","reason_options":[{"t":"서운해요·아쉬워요처럼 속상한 마음도 말로 나타내니까","correct":true},{"t":"나쁜 기분은 말하면 안 되니까","mis":"K1-2-u1-X12"}],"mis":"K1-2-u1-X12","explanation":["속상한 마음도 기분 말로 전할 수 있어요.","말하는 방법이 중요한 거예요.","속상할수록 「나」로 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#20','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C5',3,'mc','auto','「그네 앞에서」를 읽고 답하세요. 친구가 웃으며 「바꿔 탈까?」라고 한 까닭은 무엇인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":20,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"「그네 앞에서」를 읽고 답하세요. 친구가 웃으며 「바꿔 탈까?」라고 한 까닭은 무엇인가요?","options":[{"t":"탓하지 않고 기분을 말해 주어서","correct":true},{"t":"그네가 새것으로 바뀌어서","mis":"K1-2-u1-X09"},{"t":"더 큰 소리를 내서","mis":"K1-2-u1-X11"}],"explanation":["「나」로 시작해 기분을 말하자 친구 마음이 풀렸어요.","그네가 바뀌거나 소리를 더 낸 게 아니에요.","네 번째 줄 다음에 다섯 번째 줄이 온 까닭이에요."],"asset":{"type":"passage","lines":["그네를 타려고 한참 기다렸는데 다른 친구가 먼저 앉았어요.","나도 모르게 큰 소리가 나왔어요. \"너는 왜 새치기를 하니!\"","그 말을 들은 친구의 얼굴이 굳었어요. 마음이 편하지 않았어요.","숨을 한 번 쉬고 다시 말했어요. \"나는 오래 기다려서 마음이 급했어.\"","친구가 웃으며 말했어요. \"몰랐어. 열까지 세고 바꿔 탈까?\""],"title":"그네 앞에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#21','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C5',3,'error','auto','「나는 화가 났어.」 이 말에는 무엇이 빠졌나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":21,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 화가 났어.」 이 말에는 무엇이 빠졌나요?","options":[{"t":"무슨 일이 있었는지가 빠졌어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」이 빠졌어요","mis":"K1-2-u1-X09"},{"t":"말이 너무 길어요","mis":"K1-2-u1-X11"}],"explanation":["왜 화가 났는지 있었던 일을 말해야 해요.","「나는」은 있고, 길지도 않아요.","「나는 ○○해서 화가 났어」로 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#22','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C6',3,'error','auto','「우유가 고양이를 마십니다.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":22,"concept":"K1-2-u1-C6","difficulty":3,"kind":"error","stem":"「우유가 고양이를 마십니다.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"누가와 무엇을 자리가 바뀌었어요 — 고양이가 우유를 마십니다","correct":true,"mis_target":"K1-2-u1-X13"},{"t":"「마십니다」가 잘못이에요","mis":"K1-2-u1-X14"},{"t":"「우유」를 빼야 해요","mis":"K1-2-u1-X13"}],"explanation":["마시는 것은 고양이예요.","누가(고양이가) 무엇을(우유를) 어찌하다(마십니다) 차례로 고쳐요.","누가 하는 일인지 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#23','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C3',4,'sa','auto','「마음이 사르르 풀렸어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u1-C3","difficulty":4,"kind":"sa","stem":"「마음이 사르르 풀렸어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.","answer":["풀려요","풀렸어요","풀림","풀렸어","편안해요","편안해","편안했어요","편해요","편해","좋아요","좋았어요","기뻐요","안심","안심돼요","누그러져요","부드러워요"],"explanation":["사르르는 굳었던 마음이 풀리는 것이에요.","화나거나 무서운 마음이 아니에요.","눈이 녹는 모습을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#24','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C5',4,'essay','teacher','「너 때문에 내 그림이 지워졌잖아!」를 「나」로 시작하는 말로 바꿔 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"「너 때문에 내 그림이 지워졌잖아!」를 「나」로 시작하는 말로 바꿔 쓰세요.","answer_guide":{"answer":"예: 나는 그림이 지워져서 속상했어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","「너 때문에」 대신 지워진 일을 말해요.","첫 낱말을 「나」로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#25','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C2',4,'essay','teacher','「바람이 불어요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"「바람이 불어요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.","answer_guide":{"answer":"예: 바람이 살랑살랑 불어요. / 바람이 쌩쌩 불어요. — 바람과 어울리는 흉내 내는 말이면 맞아요.","scoring_points":["흉내 내는 말이 들어갔는가","바람과 어울리는가","문장이 자연스러운가"]},"explanation":["살랑살랑·쌩쌩처럼 바람의 모양이나 소리를 넣어요.","아삭아삭처럼 상관없는 소리는 어긋나요.","바람 부는 날을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#1','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C1',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],false,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"딸랑딸랑","correct":true},{"t":"팔랑팔랑","mis":"K1-2-u1-X02"},{"t":"깡충깡충","mis":"K1-2-u1-X02"}],"explanation":["딸랑딸랑은(는) 종이 울리는 소리를 그대로 옮긴 말이에요.","나머지는 눈으로 본 모양을 옮긴 말이에요.","입으로 내 보고 귀로 들리는 것인지 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#2','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C1',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K1-2-u1-X02']::text[],false,'{"seq":2,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"살랑살랑","correct":true},{"t":"삐악삐악","mis":"K1-2-u1-X02"},{"t":"첨벙첨벙","mis":"K1-2-u1-X02"}],"explanation":["살랑살랑은(는) 꼬리를 흔드는 모양을 옮긴 말이에요.","나머지는 귀로 들은 소리를 옮긴 말이에요.","몸으로 따라 할 수 있으면 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#3','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C4',1,'mc','auto','다음 가운데 기분을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u1-X08']::text[],false,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"다음 가운데 기분을 나타내는 말은 어느 것인가요?","options":[{"t":"걱정돼요","correct":true},{"t":"연필","mis":"K1-2-u1-X08"},{"t":"줄넘기","mis":"K1-2-u1-X08"}],"explanation":["걱정돼요는 마음을 나타내는 말이에요.","연필은 물건, 줄넘기는 하는 일이에요.","「마음이 ○○해요」로 바꿔 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#4','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C4',1,'mc','auto','이사 간 친구를 오랜만에 만났어요. 내 기분에 어울리는 말은 어느 것인가요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"이사 간 친구를 오랜만에 만났어요. 내 기분에 어울리는 말은 어느 것인가요?","options":[{"t":"반가워요","correct":true},{"t":"서운해요","mis":"K1-2-u1-X07"},{"t":"심심해요","mis":"K1-2-u1-X07"}],"explanation":["보고 싶던 친구를 만나면 반가워요.","서운하거나 심심한 일이 아니에요.","오랜만에 보는 얼굴을 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
