INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#6','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C5',1,'mc','auto','듣는 사람을 생각한 말은 어느 것인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X10']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"듣는 사람을 생각한 말은 어느 것인가요?","options":[{"t":"나는 갑자기 밀려서 놀랐어.","correct":true},{"t":"너 진짜 밉다!","mis":"K1-2-u1-X09"},{"t":"아, 몰라. 저리 가.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말했어요.","「밉다」와 「저리 가」는 탓하고 밀어내는 말이에요.","놀란 마음을 그대로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#7','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C6',1,'mc','auto','동생이 무엇을 할까요? 알맞은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":7,"concept":"K1-2-u1-C6","difficulty":1,"kind":"mc","stem":"동생이 무엇을 할까요? 알맞은 문장은 어느 것인가요?","options":[{"t":"동생이 그림을 그립니다.","correct":true},{"t":"그림이 동생을 그립니다.","mis":"K1-2-u1-X13"},{"t":"동생이 그림을 먹습니다.","mis":"K1-2-u1-X14"}],"explanation":["누가(동생이) 무엇을(그림을) 어찌하다(그립니다) 차례예요.","그림이 동생을 그릴 수 없고, 그림을 먹을 수도 없어요.","그림을 보고 누가 하는 일인지 짚어요."],"asset":{"type":"scene","icon":"🧒🖍️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#8','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C3',1,'mc','auto','「두근두근」이 나타내는 마음은 어느 것인가요?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「두근두근」이 나타내는 마음은 어느 것인가요?","options":[{"t":"설레요","correct":true},{"t":"지루해요","mis":"K1-2-u1-X06"},{"t":"편안해요","mis":"K1-2-u1-X06"}],"explanation":["두근두근은 가슴이 뛰는 설레는 마음이에요.","지루하거나 편안할 때는 가슴이 뛰지 않아요.","가슴에 손을 대 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#9','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C1',2,'match','auto','그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C1","difficulty":2,"kind":"match","stem":"그림과 어울리는 흉내 내는 말을 선으로 이어 보세요.","pairs":[{"l":"🐈 고양이","r":"야옹"},{"l":"☁️ 구름","r":"뭉게뭉게"},{"l":"🍎 사과 먹기","r":"아삭아삭"}],"mis":"K1-2-u1-X03","explanation":["고양이는 야옹, 구름은 뭉게뭉게예요.","사과를 먹으면 아삭아삭 소리가 나요.","그림을 보고 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#10','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C2',2,'mc','auto','시계 소리가 들리는 것 같은 문장은 어느 것인가요?',ARRAY['K1-2-u1-X04','K1-2-u1-X03']::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"시계 소리가 들리는 것 같은 문장은 어느 것인가요?","options":[{"t":"시계가 똑딱똑딱 가요.","correct":true},{"t":"시계가 가요.","mis":"K1-2-u1-X04"},{"t":"시계가 데굴데굴 가요.","mis":"K1-2-u1-X03"}],"explanation":["똑딱똑딱은 시계 소리예요.","흉내 내는 말이 없으면 소리가 안 들리고, 데굴데굴은 구르는 모양이에요.","시계 곁에서 귀를 기울여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
