INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#16','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C3',2,'ox','auto','「콩닥콩닥」은 떨리는 마음을 나타내요.',ARRAY['K1-2-u1-X05']::text[],false,'{"seq":16,"concept":"K1-2-u1-C3","difficulty":2,"kind":"ox","stem":"「콩닥콩닥」은 떨리는 마음을 나타내요.","answer":"O","reason_options":[{"t":"가슴이 뛰는 것을 옮긴 말이니까","correct":true},{"t":"콩닥콩닥은 문 두드리는 소리니까","mis":"K1-2-u1-X05"}],"mis":"K1-2-u1-X05","explanation":["콩닥콩닥은 가슴이 뛰는 떨리는 마음이에요.","문 두드리는 소리는 똑똑이에요.","발표 앞의 나를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#17','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C1',3,'error','auto','모양을 흉내 낸 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#18','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C2',3,'error','auto','「비가 짹짹 내려요.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],false,'{"seq":18,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「비가 짹짹 내려요.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"짹짹은 새소리라 비가 내리는 장면과 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"비에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「내려요」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["비가 내리는 소리는 주룩주룩이에요.","짹짹은 새가 우는 소리예요.","장면을 먼저 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#19','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C4',3,'ox','auto','내 기분에 꼭 맞는 말을 찾으면 마음이 더 잘 전해져요.',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":19,"concept":"K1-2-u1-C4","difficulty":3,"kind":"ox","stem":"내 기분에 꼭 맞는 말을 찾으면 마음이 더 잘 전해져요.","answer":"O","reason_options":[{"t":"기쁘다 하나보다 뿌듯하다·반갑다처럼 딱 맞는 말이 마음을 정확히 알려 주니까","correct":true},{"t":"기분 말은 아무거나 써도 다 똑같으니까","mis":"K1-2-u1-X07"}],"mis":"K1-2-u1-X07","explanation":["마음에 꼭 맞는 말을 고를수록 잘 전해져요.","아무 말이나 쓰면 내 마음과 어긋날 수 있어요.","상 받은 기분은 기뻐요보다 뿌듯해요가 더 가까워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#20','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C5',3,'mc','auto','「빌려준 색연필」을 읽고 답하세요. 짝이 「새것으로 사 줄게」라고 한 까닭은 무엇인가요?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":20,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"「빌려준 색연필」을 읽고 답하세요. 짝이 「새것으로 사 줄게」라고 한 까닭은 무엇인가요?","options":[{"t":"탓하지 않고 속상한 마음을 말해 주어서","correct":true},{"t":"색연필이 더 비싸져서","mis":"K1-2-u1-X09"},{"t":"더 크게 소리쳐서","mis":"K1-2-u1-X11"}],"explanation":["「나」로 시작해 기분을 말하자 짝이 사과했어요.","값이나 소리 때문이 아니에요.","네 번째 줄과 다섯 번째 줄을 이어 읽어요."],"asset":{"type":"passage","lines":["짝이 내 색연필을 빌려 가서 부러뜨렸어요.","나는 \"너는 왜 남의 걸 함부로 써!\" 하고 소리쳤어요.","짝은 고개를 푹 숙였어요.","나는 다시 말했어요. \"나는 아끼던 색연필이 부러져서 속상했어.\"","짝이 말했어요. \"미안해. 내가 새것으로 사 줄게.\""],"title":"빌려준 색연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#21','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C5',3,'error','auto','「나는 네가 새치기해서 나쁜 애라고 생각했어.」 이 말은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":21,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 네가 새치기해서 나쁜 애라고 생각했어.」 이 말은 무엇이 잘못되었나요?","options":[{"t":"「나」로 시작했지만 내 기분 대신 상대를 나쁘다고 탓했어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나」로 시작한 것이 잘못이에요","mis":"K1-2-u1-X09"},{"t":"더 길게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["「나쁜 애」는 탓하는 말이에요.","「나는 오래 기다려서 급했어」처럼 내 기분을 말해요.","「나」 뒤에 탓이 오면 마음이 굳어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#22','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C6',3,'error','auto','「그림이 동생을 그립니다.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":22,"concept":"K1-2-u1-C6","difficulty":3,"kind":"error","stem":"「그림이 동생을 그립니다.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"누가와 무엇을 자리가 바뀌었어요 — 동생이 그림을 그립니다","correct":true,"mis_target":"K1-2-u1-X13"},{"t":"「그립니다」가 잘못이에요","mis":"K1-2-u1-X14"},{"t":"「그림」을 빼야 해요","mis":"K1-2-u1-X13"}],"explanation":["그리는 것은 동생이에요.","누가(동생이) 무엇을(그림을) 어찌하다(그립니다) 차례로 고쳐요.","누가 하는 일인지 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#23','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C3',4,'sa','auto','「마음이 훨훨 나는 것 같았어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u1-C3","difficulty":4,"kind":"sa","stem":"「마음이 훨훨 나는 것 같았어요.」 이 말이 나타내는 마음을 한 낱말로 쓰세요.","answer":["신나요","신나","신났어요","신났어","신남","기뻐요","기뻐","기뻤어요","기쁘다","기쁨","즐거워요","즐거워","즐거웠어요","행복해요","행복해","뿌듯해요","뿌듯해","날아갈것같아요"],"explanation":["훨훨은 신나서 날아갈 것 같은 마음이에요.","속상하거나 무서운 마음이 아니에요.","줄넘기를 열 번 넘은 나를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#24','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C5',4,'essay','teacher','「너는 왜 내 지우개를 가져가!」를 「나」로 시작하는 말로 바꿔 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"「너는 왜 내 지우개를 가져가!」를 「나」로 시작하는 말로 바꿔 쓰세요.","answer_guide":{"answer":"예: 나는 지우개가 없어져서 당황했어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","「왜 가져가」 대신 지우개가 없어진 일을 말해요.","첫 낱말을 「나」로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#25','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C2',4,'essay','teacher','「아기가 웃어요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"「아기가 웃어요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.","answer_guide":{"answer":"예: 아기가 까르르 웃어요. / 아기가 방긋방긋 웃어요. — 웃는 소리나 모양에 어울리면 맞아요.","scoring_points":["흉내 내는 말이 들어갔는가","웃는 장면과 어울리는가","문장이 자연스러운가"]},"explanation":["까르르·방긋방긋처럼 웃는 소리나 모양을 넣어요.","쨍그랑처럼 상관없는 소리는 어긋나요.","아기가 웃는 모습을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
